func ResourceSchema_code_repo(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "CodeRepo is a catalogue entry for a single source code repository that Wayfinder can reach, naming the repository and the source control connection it is reached through. Registering a repository as a CodeRepo checks once that Wayfinder really can reach it, and gives other resources — such as a SourceProposal — a stable name to refer to it by, so they do not each have to repeat the connection details. A CodeRepo records what the repository is and whether it is still reachable; it does not itself change anything in the repository.\n\nA repository is owned by exactly one workspace, which is required: there is no tenant-level repository. To let another workspace use it, grant that workspace in spec.usableBy — the repository stays where it is, and anything in the other workspace names it as GitHub does, \"github.com/OWNER/REPO\".", Attributes: map[string]rschema.Attribute{"default_branch": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DefaultBranch overrides the branch Wayfinder treats as this repository's main working branch, e.g. \"main\". Leave it empty to use the default branch reported by the provider, which is published in the status."},
		"description":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is an optional repository description applied when Provision creates the repository. Ignored for a linked repository."},
		"display_name": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DisplayName is a friendlier name to show for this repository in place of its repository name, e.g. \"Wayfinder Platform\"."},
		"github_access": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "GitHubAccess names the GitHub teams and users in the organization given GitHub's Admin or Write role on the repository when Provision creates it, so whoever asked for it can work in it without anyone adding them on GitHub. Each name is checked against the organization first: the repository is not created while any name is a team or user the organization does not have, or while the Wayfinder GitHub App cannot read the organization's teams and members (it needs Members: read). Access is granted once, when the repository is created: changing it afterwards changes nothing on GitHub. Ignored for a linked repository.", Attributes: map[string]rschema.Attribute{"admin": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Admin names who gets GitHub's Admin role: everything Write allows, plus changing the repository's settings, branch protection and who else has access, and deleting it.", Attributes: map[string]rschema.Attribute{"teams": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Teams are the slugs of teams in the organization, as they appear in each team's URL, e.g. \"accounts-payable\" for github.com/orgs/acme/teams/accounts-payable.", ElementType: types.StringType},
			"users": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Users are the GitHub logins of members of the organization, e.g. \"octocat\". Case does not matter.", ElementType: types.StringType},
		}},
			"write": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Write names who gets GitHub's Write role: they can clone the repository, push branches, and open and review pull requests, but cannot change its settings.", Attributes: map[string]rschema.Attribute{"teams": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Teams are the slugs of teams in the organization, as they appear in each team's URL, e.g. \"accounts-payable\" for github.com/orgs/acme/teams/accounts-payable.", ElementType: types.StringType},
				"users": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Users are the GitHub logins of members of the organization, e.g. \"octocat\". Case does not matter.", ElementType: types.StringType},
			}},
		}},
		"github_org_ref": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "GitHubOrgRef names the GitHub organization connection this repository is reached through.", Attributes: map[string]rschema.Attribute{"name": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name is the name of the GitHubOrg, e.g. \"appvia\"."}}},
		"provision":      rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Provision creates the repository on GitHub if it is not there already, e.g. a new repository for a stack. Leave it false to catalogue a repository that already exists. The repository is created once and never again: one deleted on GitHub afterwards is reported as orphaned rather than made a second time."},
		"repo":           rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Repo is the repository name on its own, without the owning organization, e.g. \"wayfinder\". The organization comes from the connection."},
		"usable_by": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "UsableBy lists who may use this repository through Wayfinder, and how far. Each entry names either a subject or a Wayfinder role held at a scope, plus the access it is granted. Being able to SEE a repository is a separate question, decided by Wayfinder roles; this decides who may act on it — obtain a git credential for it, propose changes to it, or have Wayfinder read and write it on their behalf.\n\nAn empty list grants nobody anything: a repository nobody is listed on can be catalogued and read as an entry, and no work can be done against it.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"access": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Access is how far this grantee may go: \"read\" to clone and fetch, \"write\" to also push and open pull requests, or \"write-workflows\" to also change CI workflow definitions.\n\n- `read`: Clones and fetches the repository and reads its CI results — which workflow run failed, which check is red, and what has been deployed.\n\n- `write`: Additionally pushes branches, opens pull requests and comments on them.\n\n- `write-workflows`: Additionally pushes changes to CI workflow definitions under .github/workflows, which GitHub refuses at \"write\" alone. It is a level of its own because such a push changes what CI runs — on a self-hosted runner, what runs on your own machines.", Validators: []validator.String{stringvalidator.OneOf("read", "write", "write-workflows")}},
			"role": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Role grants access to any subject holding a Wayfinder role at a scope, evaluated from the roles the caller holds at the time of the request. Name the workspace those holders must hold the role in — \"*\" for every workspace, e.g. `{role: workspace.member, workspace: \"*\"}` to offer a template to the whole tenant — or set tenant to grant to holders of a tenant-level role. Leave the workspace out to grant only within the workspace that owns the repository. Exactly one of subject or role must be set.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment narrows the grant to holders of the role in a single environment. Leave it empty to require the role at workspace scope and nothing narrower, or set \"*\" to match the role held at workspace scope or in any one environment. It is inert where the granting resource pins an environment of its own, and has no meaning alongside tenant, which names a scope no environment sits under."},
				"role":      rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Role is the name of the Wayfinder role whose holders are granted, e.g. \"deployer\", \"viewer\" or \"workspace.manager\"."},
				"tenant":    rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Tenant grants to holders of the role at tenant scope, such as \"tenant.owner\" - a tenant-level role holding rather than one held in any particular workspace, so the two never match the same people. It may only be set where the granting resource reaches the whole tenant, and is mutually exclusive with workspace."},
				"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace is the workspace holders must hold the role in. \"*\" matches any workspace. It is inert where the granting resource pins a workspace of its own, and is mutually exclusive with tenant."},
			}},
			"subject": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Subject is the user, service account, group, AI agent, workflow or webhook this grant is for. Exactly one of subject or role must be set.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
				"kind":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
				"name":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
				"tenant":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
				"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			}},
		}}},
		"visibility":     rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Visibility is the desired repository visibility when Provision is set: \"public\", \"private\" or \"internal\". Empty defaults to private. Ignored for a linked (non-provisioned) repository."},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
