func ResourceSchema_dns_zone(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "DNSZone represents a hosted DNS zone for a domain in AWS Route 53, Azure DNS, or Google Cloud DNS. Wayfinder creates the zone in the cloud account you point it at, publishes its authoritative nameservers, and — where you name a parent zone that Wayfinder also manages — sets up and checks the delegation between the two. Clusters and applications draw their host names from the zone's entry templates, so deployments get working DNS without anyone editing records by hand. A zone can also be marked unmanaged, in which case Wayfinder only verifies it exists and uses it as a delegation parent.", Attributes: map[string]rschema.Attribute{"app_dns_entry_template": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "AppDNSEntryTemplate defines how the 'getDNSEntry' template function works when templating application deployments (i.e. those requested through Wayfinder.yaml / 'wf up' / 'wf deploy')\n\nThe available template variables are: * {{ .Cluster }} - name of the cluster (max 10 characters alphanumeric) * {{ .Stack }} - name of the stack (i.e. Wayfinder.yaml 'name', max 32 characters alphanumeric with - and . allowed) * {{ .StackInstance }} - name of the stack instance (max 32 characters alphanumeric with - and . allowed) * {{ .StackInstanceClean }} - name of the stack instance with any stack name prefix or suffix removed (max 32 characters alphanumeric with - and . allowed) * {{ .MultiTenant }} - true if the stack is in a different workspace to the cluster * {{ .Prefix }} - any prefix supplied to the 'getDNSEntry' template function * {{ .Domain }} - the domain of this zone - the provided template MUST end with this\n\nExamples: * Shared DNS zone for all apps/envs:\n  \"{{ if .Prefix }}{{ .Prefix }}-{{ end }}{{ .StackInstance }}.{{ .Domain }}\"\n* Dedicated DNS zone for a single app environment (e.g. your production vanity domain):\n  \"{{ if .Prefix }}{{ .Prefix }}.{{ end }}{{ .Domain }}\""},
		"cluster_package_dns_entry_template": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ClusterPackageDNSEntryTemplate defines how the 'getDNSEntry' template function works when templating cluster-scoped packages (i.e. those used on a cluster plan).\n\nThe available template variables are: * {{ .Cluster }} - name of the cluster (max 10 characters alphanumeric) * {{ .Package }} - name of the package * {{ .Prefix }} - any prefix supplied to the 'getDNSEntry' template function * {{ .Domain }} - the domain of this zone - the provided template MUST end with this\n\nExample: \"{{ if .Prefix }}{{ .Prefix }}-{{ end }}{{ .Package }}.{{ .Cluster }}.{{ .Domain }}\""},
		"cluster_roles": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "ClusterRoles names the Kubernetes cluster roles anything deployed through this target is bound to, for a kubernetes destination — the access it deploys with. Each entry names a role the cluster owner has allocated to your workspace and the scope to bind it at, e.g. {\"clusterRoleName\": \"cluster-admin\", \"roleBindingType\": \"Cluster\"}. Left unset, the cluster's default deployment role is used where it has one, and at least one role must be named where it does not. A cloud or service destination uses identityRef instead.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"cluster_role_name": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "ClusterRoleName is the name of the ClusterRole in the target cluster, chosen from the roles the cluster owner has allocated to your workspace, e.g. \"cluster-admin\"."},
			"role_binding_type": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RoleBindingType is the scope to bind at: Namespace (the default) binds in the target's namespace, Cluster binds cluster-wide.\n\n- `Namespace`: Creates RoleBindings in specific namespaces\n\n- `Cluster`: Creates ClusterRoleBindings for cluster-wide access", Validators: []validator.String{stringvalidator.OneOf("Namespace", "Cluster")}},
		}}},
		"description":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description provides an optional human-readable description and should be used to provide context to users about what this zone should be used for."},
		"destination":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Destination is the place this target names, e.g. \"aws:123456789012:eu-west-2\", \"k8s:my-workspace/dev/my-cluster:my-namespace\" or \"srv:vault.internal.corp:8443\"."},
		"domain":       rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Domain is the fully-qualified domain name this zone is authoritative for, e.g. \"dev.example.com\"."},
		"identity_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "IdentityRef references the ExternalIdentity Wayfinder authenticates with, for a cloud or service destination, e.g. \"my-workspace/aws-nonprod\". A kubernetes destination uses clusterRoles instead."},
		"parent_zone": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "ParentZone should be set to make this zone a child of another zone managed by Wayfinder, e.g. a zone for \"dev.example.com\" whose parent holds \"example.com\". Setting this allows Wayfinder to automatically manage the delegation of this zone.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment identifies the environment in which this item exists."},
			"name":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name is the object name of the referenced item"},
			"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace identifies the workspace in which this item exists."},
		}},
		"private_zone":  rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "PrivateZone indicates that this is a private DNS zone, resolvable only from the networks listed in the provider details, if applicable for the provider."},
		"spec_provider": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Provider is the cloud provider hosting this zone: \"aws\" (Route 53), \"azure\" (Azure DNS), or \"gcp\" (Google Cloud DNS)."},
		"provider_details": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "ProviderDetails carries the extra settings needed by a particular DNS provider, such as the networks a private zone is resolvable from.", Attributes: map[string]rschema.Attribute{"aws": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "AWS holds parameters specific to an AWS DNS zone. Present only if type is AWS.", Attributes: map[string]rschema.Attribute{"private_zone_vpcs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "PrivateZoneVPCs is a list of VPC IDs (and the regions of those VPCs) in which a private AWS DNS zone should be resolvable.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"cluster_roles": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "ClusterRoles names the Kubernetes cluster roles anything deployed through this target is bound to, for a kubernetes destination — the access it deploys with. Each entry names a role the cluster owner has allocated to your workspace and the scope to bind it at, e.g. {\"clusterRoleName\": \"cluster-admin\", \"roleBindingType\": \"Cluster\"}. Left unset, the cluster's default deployment role is used where it has one, and at least one role must be named where it does not. A cloud or service destination uses identityRef instead.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"cluster_role_name": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "ClusterRoleName is the name of the ClusterRole in the target cluster, chosen from the roles the cluster owner has allocated to your workspace, e.g. \"cluster-admin\"."},
			"role_binding_type": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RoleBindingType is the scope to bind at: Namespace (the default) binds in the target's namespace, Cluster binds cluster-wide.\n\n- `Namespace`: Creates RoleBindings in specific namespaces\n\n- `Cluster`: Creates ClusterRoleBindings for cluster-wide access", Validators: []validator.String{stringvalidator.OneOf("Namespace", "Cluster")}},
		}}},
			"destination":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Destination is the place this target names, e.g. \"aws:123456789012:eu-west-2\", \"k8s:my-workspace/dev/my-cluster:my-namespace\" or \"srv:vault.internal.corp:8443\"."},
			"identity_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "IdentityRef references the ExternalIdentity Wayfinder authenticates with, for a cloud or service destination, e.g. \"my-workspace/aws-nonprod\". A kubernetes destination uses clusterRoles instead."},
			"region":       rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Region is the AWS region in which the VPC exists, e.g. \"eu-west-2\". It must agree with the region named by destination."},
			"vpc_id":       rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "VPCID is the ID of the AWS VPC to associate the private hosted zone with, e.g. \"vpc-1234abc0\" or \"vpc-1234567890abcdef0\"."},
		}}},
		}},
			"azure": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Azure holds parameters specific to an Azure DNS zone. Present only if type is Azure.", Attributes: map[string]rschema.Attribute{"private_zone_v_net_ids": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "PrivateZoneVNetIDs is a list of virtual network IDs a private Azure DNS zone should be resolvable from, e.g. \"/subscriptions/00000000-0000-0000-0000-000000000000/resourceGroups/my-rg/providers/Microsoft.Network/virtualNetworks/my-vnet\". The identity used for this zone must be allowed the 'join' action on the virtual networks listed here.", ElementType: types.StringType},
				"region":         rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Region is the Azure region the resource group holding this zone is created in, e.g. \"uksouth\". Resource groups are regional in Azure, so a region is required for an Azure DNS zone even though the zone itself is global."},
				"resource_group": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ResourceGroup identifies an existing resource group to place this DNS zone in, e.g. \"my-dns-rg\". Leave it unset to have a new resource group created for the zone."},
			}},
			"gcp":  rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "GCP holds parameters specific to a GCP DNS zone. Present only if type is GCP.", Attributes: map[string]rschema.Attribute{"private_zone_vpcs": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "PrivateZoneVPCs is a list of VPC network IDs a private Google Cloud DNS zone should be resolvable from, e.g. \"projects/my-project/global/networks/my-network\".", ElementType: types.StringType}}},
			"type": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Type selects which provider block applies: AWS, Azure, or GCP.\n\n- `AWS`: Indicates an AWS Route 53 hosted zone.\n\n- `Azure`: Indicates an Azure DNS zone.\n\n- `GCP`: Indicates a Google Cloud DNS managed zone.", Validators: []validator.String{stringvalidator.OneOf("AWS", "Azure", "GCP")}},
		}},
		"unmanaged":      rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Unmanaged should be set to true to indicate that this zone should not be built or deleted by Wayfinder, but should be verified to exist in the specified DNS provider and, thus, will be usable as a parent zone."},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"environment":    rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
