func ResourceSchema_github_org(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "GitHubOrg is a connection between Wayfinder and a GitHub organization, established by installing the Wayfinder GitHub App into that organization. The connection lets Wayfinder read and raise changes against the repositories the organization has shared with the App, and it lists those repositories in its status so you can see exactly what Wayfinder can reach. Register an individual repository as a CodeRepo to refer to it elsewhere in Wayfinder. A GitHubOrg is held at tenant level and can be used by every workspace in the tenant.", Attributes: map[string]rschema.Attribute{"install_grant": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "InstallGrant is the short-lived token Wayfinder issues when you return from authorising the Wayfinder GitHub App on GitHub. It lists the accounts the App is installed on that you can see, and says which you may connect: an organization you are an owner of, your own personal account, or an installation you asked an owner to approve. Supply it when creating a connection, or when updating one to reconnect it to the installation the grant holds for the same organization after the App was installed again. It is consumed and never stored. The same organization may be connected to several tenants, once in each. The GitHub connect flow supplies it automatically."},
		"organization":   rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Organization is the GitHub organization or personal account this connection is to, given as its GitHub login, e.g. \"appvia\". It must be one of the accounts the install grant covers that you are allowed to connect.", PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
