func ResourceSchema_group(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Group is a named collection of users and service accounts, used to keep permission management manageable: grant roles to the group once, then control who holds those roles by changing its membership. Groups can also be nested as members of other groups.", Attributes: map[string]rschema.Attribute{"description": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a human-readable description of what this group is for."},
		"managers": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Managers are the subjects allowed to change this group's membership. They do not need to be members themselves, and being a manager does NOT convey membership - so a manager does not receive the roles granted to the group. If empty, only tenant owners can change the membership.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"kind":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"name":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"tenant":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
		}}},
		"members": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Members are the users, service accounts and other groups that belong to this group, and so receive every role granted to it.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"kind":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"name":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"tenant":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
			"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: ""},
		}}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
