func ResourceSchema_integration(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Integration represents an activated integration in your tenant. There are two kinds:\n\n  - Feature integrations (e.g. ai, github, terraform) are Wayfinder-provided\n    capabilities. Enable one to make its functionality available in your tenant.\n    Some extensible feature integrations (e.g. http) also allow you to attach your\n    own MCP servers, webhooks, and web APIs to them.\n  - Custom integrations are ones you create and own. Your MCP servers, webhooks,\n    and web APIs belong to a custom integration, which groups them and gives them\n    context.", Attributes: map[string]rschema.Attribute{"description": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a short description of the integration."},
		"enabled":        rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Enabled indicates whether this feature integration is active. Only applies to feature integrations; custom integrations you own do not have an enable/disable toggle."},
		"params":         rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Params are the configuration values for this integration. For integrations created from a catalogue template, params are validated against the template's parameter definitions. For integrations you created yourself, any params are accepted.", ElementType: jsontypes.NormalizedType{}},
		"template_ref":   rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "TemplateRef links a custom integration to the catalogue template it was created from, e.g. \"wayfinder.dns@7\", and records the template version you are on so an upgrade can be offered. It appears only on custom integrations created from a template: a custom created from scratch has none, and a feature integration never carries one (a feature is enabled, not created from a template). Set by Wayfinder; read-only.", PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace(), stringplanmodifier.UseStateForUnknown()}},
		"type":           rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "Type indicates whether this is a Wayfinder-provided feature integration or one you own. It is the integration's identity: \"feature\" is stamped by Wayfinder when you enable a catalogue feature; integrations you create are always \"custom\". Set by Wayfinder; read-only. You cannot create a feature integration yourself, and the type cannot change once set.\n\n- `feature`: Is a Wayfinder-provided capability you enable or disable for your tenant, e.g. ai, github, or terraform.\n\n- `custom`: Is an integration you own. Your MCP servers, webhooks, and web APIs belong to this integration.", PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace(), stringplanmodifier.UseStateForUnknown()}, Validators: []validator.String{stringvalidator.OneOf("feature", "custom")}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
func DataSourceSchema_integration(ctx context.Context) dschema.Schema {
	return dschema.Schema{MarkdownDescription: "Integration represents an activated integration in your tenant. There are two kinds:\n\n  - Feature integrations (e.g. ai, github, terraform) are Wayfinder-provided\n    capabilities. Enable one to make its functionality available in your tenant.\n    Some extensible feature integrations (e.g. http) also allow you to attach your\n    own MCP servers, webhooks, and web APIs to them.\n  - Custom integrations are ones you create and own. Your MCP servers, webhooks,\n    and web APIs belong to a custom integration, which groups them and gives them\n    context.", Attributes: map[string]dschema.Attribute{"description": dschema.StringAttribute{Computed: true, MarkdownDescription: "Description is a short description of the integration."},
		"enabled":      dschema.BoolAttribute{Computed: true, MarkdownDescription: "Enabled indicates whether this feature integration is active. Only applies to feature integrations; custom integrations you own do not have an enable/disable toggle."},
		"params":       dschema.MapAttribute{Computed: true, MarkdownDescription: "Params are the configuration values for this integration. For integrations created from a catalogue template, params are validated against the template's parameter definitions. For integrations you created yourself, any params are accepted.", ElementType: jsontypes.NormalizedType{}},
		"template_ref": dschema.StringAttribute{Computed: true, MarkdownDescription: "TemplateRef links a custom integration to the catalogue template it was created from, e.g. \"wayfinder.dns@7\", and records the template version you are on so an upgrade can be offered. It appears only on custom integrations created from a template: a custom created from scratch has none, and a feature integration never carries one (a feature is enabled, not created from a template). Set by Wayfinder; read-only."},
		"type":         dschema.StringAttribute{Computed: true, MarkdownDescription: "Type indicates whether this is a Wayfinder-provided feature integration or one you own. It is the integration's identity: \"feature\" is stamped by Wayfinder when you enable a catalogue feature; integrations you create are always \"custom\". Set by Wayfinder; read-only. You cannot create a feature integration yourself, and the type cannot change once set.\n\n- `feature`: Is a Wayfinder-provided capability you enable or disable for your tenant, e.g. ai, github, or terraform.\n\n- `custom`: Is an integration you own. Your MCP servers, webhooks, and web APIs belong to this integration.", Validators: []validator.String{stringvalidator.OneOf("feature", "custom")}},
		"id":           dschema.StringAttribute{Computed: true},
		"name":         dschema.StringAttribute{Required: true, Optional: false},
		"workspace":    dschema.StringAttribute{Required: false, Optional: true},
		"labels":       dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"annotations":  dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"status":       dschema.SingleNestedAttribute{Computed: true, Attributes: map[string]dschema.Attribute{"status": dschema.StringAttribute{Computed: true}, "message": dschema.StringAttribute{Computed: true}, "detail": dschema.StringAttribute{Computed: true}}},
		"status_json":  dschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
	}}
}
func ResourceSchema_invite(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Invite is an invitation for someone to join a tenant, addressed to an email address and carrying the roles and workspace memberships they will be granted when they accept. The invitation link is emailed to them and is valid until the invite expires; revoking an invite means deleting it.", Attributes: map[string]rschema.Attribute{"auto_join": rschema.BoolAttribute{Optional: true, Computed: true, MarkdownDescription: "AutoJoin indicates the person was admitted automatically because their email domain is allowed for this tenant, rather than being invited by name. Set by Wayfinder.", PlanModifiers: []planmodifier.Bool{boolplanmodifier.UseStateForUnknown()}},
		"email":      rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Email is the email address the invitation is sent to, e.g. \"alex@acme.com\"."},
		"expires_at": rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "ExpiresAt is when the invitation stops being usable. After this point the invite reads as expired and a new one must be sent.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"invited_by": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "InvitedBy is the username of the person who created the invite."},
		"message":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Message is an optional personal note included in the invitation email."},
		"roles":      rschema.ListAttribute{Required: true, Optional: false, MarkdownDescription: "Roles are the names of the Wayfinder roles granted when the invite is accepted. At least one is required, e.g. [\"tenant.member\"].", ElementType: types.StringType},
		"scope":      rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "Scope is how far the granted access reaches. Only tenant owners and admins can create invites.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}, Validators: []validator.String{stringvalidator.OneOf("tenant")}},
		"tenant":     rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Tenant is the tenant the invite belongs to. It is filled in only when invites are listed across tenants, for example when showing someone every invitation waiting for them, and is empty otherwise."},
		"token_id":   rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "TokenID identifies the invitation link that is currently valid. The link itself is only ever emailed to the invited person and is never stored, so it cannot be retrieved; resending the invite issues a new link and invalidates the previous one.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"workspace_roles": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "WorkspaceRoles are workspace-scoped roles granted when the invite is accepted, each entry naming one workspace and the roles granted in it, e.g. workspace \"team-a\" with role \"workspace.member\". Use this to invite someone straight into a workspace instead of granting them access afterwards.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"roles": rschema.ListAttribute{Required: true, Optional: false, MarkdownDescription: "Roles are the names of the Wayfinder roles granted in the workspace, e.g. [\"workspace.member\"]. Each role must be valid at workspace scope.", ElementType: types.StringType},
			"workspace": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Workspace is the name of the workspace the roles are granted in, e.g. \"team-a\". The workspace must already exist in the tenant."},
		}}},
		"workspaces":     rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Workspaces are the names of the workspaces to add the invited person to. They are added to each named workspace's members group on acceptance.", ElementType: types.StringType},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
