func ResourceSchema_repo_template(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "RepoTemplate registers an upstream repository as a scaffolding template. The template's definition — name, description, language, inputs and skeleton location — lives inside the template repository as a wayfinder-template.yaml manifest, so a template is versioned together with its content. Wayfinder keeps a copy of that manifest, refreshed from the source, for catalogue listings and input forms; scaffolding renders the skeleton tree with a user's inputs and pushes the result as the initial commit of a newly-created repository.\n\nThe source is either a CodeRepo (private repositories, accessed through the GitHub App) or a public https git URL (community templates, read anonymously). Exactly one must be set.", Attributes: map[string]rschema.Attribute{"category": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Category is a cloud-agnostic taxonomy entry (e.g. \"service\", \"library\", \"pipeline\") classifying what this template scaffolds, drawn from the curated list served by the catalogue. Set by the platform team when registering the template. The catalogue filters and searches on it. Free-form (validated for format only); the curated list is a picker convenience. Language/framework and other free-form axes are metadata.labels, not this."},
		"code_repo_ref":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "CodeRepoRef names the repository holding the template, e.g. \"github.com/appvia/templates\" — use it for a template repository read through the GitHub App, which is the only way to reach a private one. It must be registered with Wayfinder, and the workspace that owns it must have shared it in its spec.usableBy. Exactly one of codeRepoRef or url must be set."},
		"display_name":   rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DisplayName is an optional human-friendly label for UI. The synced manifest's name (status.manifest.name) is preferred when present."},
		"path":           rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Path is the directory within the repository containing the template's wayfinder-template.yaml manifest (and, relative to it, the skeleton files). Empty means the repository root, allowing one repository to host several templates in subdirectories."},
		"ref":            rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Ref is the branch or tag to read the template from. Empty means the repository's default branch."},
		"url":            rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "URL is a public https git URL holding the template, cloned anonymously (read-only) — for community/starter templates outside a connected org. Exactly one of codeRepoRef or url must be set."},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
