func ResourceSchema_repository(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Repository is a Helm chart repository that kube resource plans can pull charts from, either an HTTP chart repository or an OCI registry. It records the repository URL, any credentials needed to authenticate to it and any private certificate authority needed to trust it, and lists the charts and versions Wayfinder found there so they can be browsed when building a plan.", Attributes: map[string]rschema.Attribute{"auth_external_identity_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "AuthExternalIdentityRef references a BasicAuth ExternalIdentity that authenticates to the repository with a username and password. The identity's spec.service host must match the repository URL host."},
		"ca_bundle":                 rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "CABundle is a PEM-encoded certificate authority bundle used to verify the repository's TLS server certificate, for repositories served from a private or internal CA. It is public trust material, not a credential, so it is held inline rather than in an ExternalIdentity, and is independent of the auth/TLS identity references (it may be set with or without a client-certificate identity)."},
		"description":               rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a short description of what this repository holds and when to use it."},
		"tls_external_identity_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "TLSExternalIdentityRef references a TLSClientCert ExternalIdentity providing a client certificate and private key for mutual TLS to the repository. The identity's spec.service host must match the repository URL host."},
		"url":                       rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "URL is the Helm repository location, including protocol and host, e.g. \"https://charts.example.com\" or \"oci://registry.example.com/charts\"."},
		"id":                        rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":                      rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":                    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":               rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":                    rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":               rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":                  timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready":            rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
