func ResourceSchema_schedule(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Schedule runs one named action on a target resource, over and over, on an interval. Each time the interval elapses Wayfinder starts a run and records it.\n\nYou can write one directly — \"call this operation every six hours\" — and you can also get one for free: a resource that lists what it wants run repeatedly, such as a WebAPI's spec.schedules, has its Schedules maintained for it by the write. Those ones are read-only, and say so: change them where they are declared, and removing the declaration removes the Schedule.\n\nEither way it is the same resource with the same behaviour. There is no second mechanism for a derived schedule, which is what stops the two drifting apart.", Attributes: map[string]rschema.Attribute{"action": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Action names what to run on the target — for a WebAPI, the operation. A target usually offers several, each of which can be scheduled separately and at its own interval, so the action is always named rather than implied."},
		"schedule": rschema.SingleNestedAttribute{Required: true, Optional: false, MarkdownDescription: "Schedule is how often to run it, and the inputs to run with.", Attributes: map[string]rschema.Attribute{"every_json": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Every is how long to wait between runs, e.g. \"15m\", \"1h\" or \"24h\". Pick a value comfortably longer than the run itself takes, and be mindful of what is at the other end: a slow daily report does not want a five-minute interval. The first run happens as soon as the schedule is enabled, and each subsequent run is timed from the start of the previous one, so runs never overlap.", CustomType: jsontypes.NormalizedType{}},
			"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs are the values to run with, validated against whatever the thing being run declares it accepts — for a WebAPI operation, its own inputs.\n\nA scheduled run has nobody to ask, so anything the run needs has to be settled when the schedule is written: a query parameter, a lookback window, a page size. An operation that requires inputs cannot be scheduled without them.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"name": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
				"value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
			}}},
		}},
		"suspend": rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Suspend stops the schedule running without deleting it or losing its history. A run already under way is left to finish."},
		"target": rschema.SingleNestedAttribute{Required: true, Optional: false, MarkdownDescription: "Target is the resource the run acts on, e.g. the WebAPI whose operation is being called. It names the kind as well as the resource, because that is what decides how a run is started — Wayfinder has to know it is scheduling a WebAPI to know that starting a run means making a call.", Attributes: map[string]rschema.Attribute{"api_group": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "APIGroup is the area of our API that this kind is defined by"},
			"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment is the environment of the object (empty for non-environment-scoped objects)"},
			"kind":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Kind is the kind of the object."},
			"name":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name is the name of the object"},
			"tenant":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Tenant is the tenant of the object"},
			"untenanted":  rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Untenanted is true if the object is specifically NOT tenant scoped."},
			"version":     rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Version is the version of the object. Only relevant if the object implements Versioned interface."},
			"workspace":   rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace unique key for the workspace (empty for tenant/global scoped)"},
		}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"environment":    rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
