func ResourceSchema_service_account(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "ServiceAccount is a non-human account for automating Wayfinder from CI pipelines, scripts and other external systems. A service account can be granted roles in the same way as a user, and authenticates using one or more credentials, each represented by a ServiceAccountCredential. A service account created without a workspace can be granted access across the whole tenant; one created within a workspace can only be used within that workspace.", Attributes: map[string]rschema.Attribute{"description": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description provides a short summary of what this service account is used for, e.g. \"Deploys team-a services from GitHub Actions\"."},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
func DataSourceSchema_service_account(ctx context.Context) dschema.Schema {
	return dschema.Schema{MarkdownDescription: "ServiceAccount is a non-human account for automating Wayfinder from CI pipelines, scripts and other external systems. A service account can be granted roles in the same way as a user, and authenticates using one or more credentials, each represented by a ServiceAccountCredential. A service account created without a workspace can be granted access across the whole tenant; one created within a workspace can only be used within that workspace.", Attributes: map[string]dschema.Attribute{"description": dschema.StringAttribute{Computed: true, MarkdownDescription: "Description provides a short summary of what this service account is used for, e.g. \"Deploys team-a services from GitHub Actions\"."},
		"id":          dschema.StringAttribute{Computed: true},
		"name":        dschema.StringAttribute{Required: true, Optional: false},
		"workspace":   dschema.StringAttribute{Required: false, Optional: true},
		"labels":      dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"annotations": dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"status":      dschema.SingleNestedAttribute{Computed: true, Attributes: map[string]dschema.Attribute{"status": dschema.StringAttribute{Computed: true}, "message": dschema.StringAttribute{Computed: true}, "detail": dschema.StringAttribute{Computed: true}}},
		"status_json": dschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
	}}
}
func ResourceSchema_service_account_credential(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "ServiceAccountCredential is a single way for a service account to authenticate to Wayfinder. A service account can have several credentials at once, allowing new credentials to be issued and old ones removed without interrupting automation. Deleting a credential immediately revokes it.", Attributes: map[string]rschema.Attribute{"client_id": rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "ClientID is the fully-qualified, non-secret client identifier for a \"Token\" credential: tenant:service-account:credential (or tenant:workspace:service-account:credential). It is set when the credential is created so client tools have a canonical value to read; present it with the client secret to the token endpoint. Empty for \"Federated\" credentials.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"expires_at": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ExpiresAt is the time at which this credential stops being accepted for authentication. If unset, the credential remains valid until it is deleted."},
		"federated": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Federated describes the inbound OIDC trust for a credential with method \"Federated\". It must be set for that method and must be empty for any other.", Attributes: map[string]rschema.Attribute{"audiences": rschema.ListAttribute{Optional: true, Computed: true, MarkdownDescription: "Audiences are the accepted values for the token's \"aud\" claim; at least one must match. When omitted it is defaulted at creation time to the canonical Wayfinder audience for the tenant, which is also the audience the workload must request.", PlanModifiers: []planmodifier.List{listplanmodifier.UseStateForUnknown()}, ElementType: types.StringType},
			"claims":  rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Claims are additional token claims that must all be present and exactly equal to the given values, for example pinning GitHub's rename-proof \"repository_owner_id\".", ElementType: types.StringType},
			"issuer":  rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Issuer is the OIDC issuer that must have signed the presented token, matched exactly against the token's \"iss\" claim. It must be an https URL with no query or fragment; OIDC discovery is performed against it at exchange time."},
			"subject": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Subject is matched against the token's \"sub\" claim. It is an exact match unless it ends with a single \"*\", which makes it a prefix match (for example \"repo:acme/app:*\"). The \"*\" is only valid as the final character and the prefix before it must be at least eight characters."},
		}},
		"method":          rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Method is how this credential authenticates: \"Token\" for a Wayfinder-issued secret token, or \"Federated\" for an inbound OIDC trust described by the federated block.\n\n- `Token`: Authenticates with a Wayfinder-issued secret token. The token is returned once when the credential is created and remains valid until the credential is deleted or its expiry passes.\n\n- `Federated`: Authenticates by exchanging a short-lived OIDC identity token from a trusted external issuer (for example GitHub Actions or another cloud) for a Wayfinder API token. No secret is stored: the trust is described entirely by the federated block.", PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}, Validators: []validator.String{stringvalidator.OneOf("Token", "Federated")}},
		"service_account": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "ServiceAccount is the name of the service account this credential authenticates. It must exist in the same workspace (or, for a service account without a workspace, the same tenant) as this credential."},
		"id":              rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":            rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":       rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":          rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":     rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":          rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":     rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":        timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready":  rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
