func ResourceSchema_stack(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Stack is a named, deployable unit of application and infrastructure within a workspace, and the lasting identity that every deployment of it belongs to. The stack's contents — its components, variables and secrets — are described in a Wayfinder.yaml, which can be held in an associated code repository. Deploying that definition into an environment with `wf deploy` or `wf up` produces a StackInstance; the Stack itself carries the name, description and repository the deployments share.", Attributes: map[string]rschema.Attribute{"created_from": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "CreatedFrom records the template this stack was scaffolded from — the template reference, the pinned template commit that was rendered, and the inputs supplied at scaffold time. It is provenance only: it is never reconciled and is immutable once set. For a stack scaffolded into an existing repository (which lands as a pull request), this records intent at creation time; the checked-in wayfinder-stack.yaml materialises when that pull request merges.", PlanModifiers: []planmodifier.Object{objectplanmodifier.RequiresReplace()}, Attributes: map[string]rschema.Attribute{"api_group": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "APIGroup is the API group of the source the stack was created from (for a template, the source control API group)."},
		"commit": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Commit is the pinned template commit that was rendered to scaffold the stack, so the origin is reproducible."},
		"inputs": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs are the values supplied to the template at scaffold time.", ElementType: jsontypes.NormalizedType{}},
		"kind":   rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Kind is the kind of the source the stack was created from, e.g. RepoTemplate."},
		"name":   rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name is the name of the source the stack was created from, e.g. the RepoTemplate name."},
	}},
		"description":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a human-readable description of the stack."},
		"repo_branch":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoBranch is the branch holding the version of this stack's Wayfinder.yaml everyone should edit, e.g. \"release\". Empty means the repository's default branch."},
		"repo_file":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoFile is the name of the stack's file within repoPath, e.g. \"prod.yaml\" for a stack defined by \"stacks/payments/prod.yaml\". Empty means \"Wayfinder.yaml\"."},
		"repo_path":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoPath is the path within that repository, relative to its root, where the stack's Wayfinder.yaml lives, e.g. \"stacks/payments\". Empty means the repository root."},
		"repo_ref":       rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoRef optionally associates this Stack with the CodeRepo that hosts its Wayfinder.yaml; when set, the UI treats that repository as the canonical location and offers AI-assisted editing against it via Pull Requests. Name the repository as \"github.com/OWNER/REPO\", e.g. \"github.com/acme/payments\". A repository another workspace owns has to have been granted write to this one, since a linked repository is one the stack opens pull requests against."},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
