func ResourceSchema_web_api(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "WebAPI is an outbound HTTP API you can call from Wayfinder: a reusable connection to a third-party system (base URL, credential and default headers) plus a set of templated operations Wayfinder invokes against it. It is the outbound counterpart of the inbound Webhook. Each operation call produces a WebAPIInvocation recording the request sent and the response received.", Attributes: map[string]rschema.Attribute{"spec_connection": rschema.SingleNestedAttribute{Required: true, Optional: false, MarkdownDescription: "Connection defines how to reach the third-party system.", Attributes: map[string]rschema.Attribute{"auth": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Auth is the credential presented on each request. Leave it unset for a service that needs none.", Attributes: map[string]rschema.Attribute{"access": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Access is the most an MCP's calls may do in the repository CodeRepoRef names: \"read\" (the default) or \"write\". A call is made at the highest level up to this that the conversation asked for and its agent holds. A web API takes the level from each operation's method instead — \"read\" for GET and HEAD, \"write\" otherwise — and refuses this field.\n\n- `read`: Clones and fetches the repository and reads its CI results — which workflow run failed, which check is red, and what has been deployed.\n\n- `write`: Additionally pushes branches, opens pull requests and comments on them.", Validators: []validator.String{stringvalidator.OneOf("read", "write")}},
		"code_repo_ref":         rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "CodeRepoRef names the repository each call works on. Requests are authenticated with a short-lived token that Wayfinder mints for that repository alone, through the App it holds for the repository's provider. No secret is stored. Mutually exclusive with ExternalIdentityRef.\n\nIt is always a whole-field \"${{ .Inputs.<name> }}\" expression naming an input of kind CodeRepo, e.g. \"${{ .Inputs.codeRepo }}\", never a literal, so the repository is chosen by whatever uses the connection: an AI conversation answers it with the repository in its source context, and a web API invocation with one of its inputs. A call is refused unless the user, agent or workflow it is made for holds the access it needs in the repository's usableBy. Only GitHub repositories are supported."},
		"external_identity_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ExternalIdentityRef names the ExternalIdentity whose credential authenticates the outbound calls. It is a single self-describing reference (\"name\", \"workspace/name\" or \"workspace/environment/name\") to an endpoint-family identity: BasicAuth, TLSClientCert, BearerToken, APIKey or OAuth2ClientCredentials. The identity's service host must match the connection's base URL host, so a credential minted for one service is never presented to another. Mutually exclusive with CodeRepoRef.\n\nAn MCP may also name an AWS identity (AWSIAMRole or AWSIAMUserKey). An AWS identity is accepted only where the connection's base URL is AWS's own MCP server, https://aws-mcp.<region>.api.aws.\n\nIt may be a literal, or a whole-field \"${{ .Inputs.<name> }}\" expression naming an input the object declares. It may be nothing else: it names a Wayfinder object, so it has to resolve without running the call — that is what lets the identity be permission-checked when you save, and what keeps it visible to \"what breaks if I delete this credential?\"."},
		"github_org_ref":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "GitHubOrgRef named the GitHub organisation a connection signed in to.\n\nDeprecated: replaced by codeRepoRef. A connection that still sets it cannot be saved, and its calls are refused."},
	}},
		"base_url": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "BaseURL is the address requests are sent to, e.g. \"https://api.example.com\". It carries the scheme and host; what follows is the caller's — a WebAPI appends each operation's path, an MCP appends its own spec.path.\n\nIt may be a literal, or an expression over the inputs the object declares, e.g. \"https://api.${{ .Inputs.site }}\". An expression lets one shipped definition serve every tenant, each supplying its own value.\n\nRequired before the object may be enabled; one you have not finished configuring may leave it blank until then."},
		"headers":  rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Headers are sent on every request, in addition to anything an individual operation adds. Values may be literals or expressions over the declared inputs. Do not set a credential header here — Auth applies the credential by its type, and a header set by hand bypasses that.\n\nOn an MCP a value may also read the arguments of the tool call it is sent with, as \"${{ .Args.<name> }}\", so one registration serves every repository or project an agent asks about instead of one per value. GitHub's hosted Actions server wants \"Mcp-Param-owner\" and \"Mcp-Param-repo\" that way: with \"${{ .Args.owner }}\" the agent passes owner and repo in the tool call, as the tool's own schema asks, and the call works. A header reading an argument the call did not carry is left off, so the server answers saying which value it wanted rather than acting on a blank one. A WebAPI has no such arguments and refuses the expression.", ElementType: types.StringType},
	}},
		"definition_ref": rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "DefinitionRef records the catalogue entry this WebAPI came from, as \"<definition>@<generation>\", e.g. \"wayfinder.github@3\". Set by Wayfinder when you install an integration from the catalogue; empty for WebAPIs you create directly. Read-only.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"description":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a short human-readable summary of what this WebAPI is for."},
		"enabled":        rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Enabled toggles whether operations on this WebAPI can be invoked. A disabled WebAPI is retained and visible but its operations are not executed."},
		"input_values": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "InputValues are the values this WebAPI was given for the inputs it declares. A WebAPI set up from a catalogue entry may leave a required value blank until you configure it, and stays disabled until you do.", Attributes: map[string]rschema.Attribute{"values": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Values are named input values matching the plan's ValueDefinitions. May contain template expressions (e.g. \"${{ .Vars.name }}\", \"${{ .Secrets.key }}\"). Resolved when Wayfinder applies the configuration — secret values are never stored here.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"name": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
			"value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
		}}},
		}},
		"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs declares the values this WebAPI needs before it can be used, so one definition can serve every tenant instead of hard-coding one tenant's address and credential. A connection field may reference them, e.g. \"https://api.${{ .Inputs.site }}\", as may any operation's path, body or headers.\n\nThese are the WebAPI's own configuration, settled once. They are not the arguments to a call: an operation declares those in its own inputs, and both share one .Inputs namespace, so a name declared here may not be redeclared by an operation.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"default_value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
			"description":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description iof the value"},
			"enum":           rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
			"identity_types": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
			"max_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
			"max_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
			"maximum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
			"min_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
			"min_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
			"minimum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
			"name":           rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name of the variable"},
			"optional":       rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
			"pattern":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
			"ref_type": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]rschema.Attribute{"filter": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
				"kind": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
			}},
			"repo_access":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
			"repo_branch_prefix": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
			"required_keys":      rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
			"schema_json":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
			"secret":             rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
			"type":               rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
		}}},
		"integration_ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "IntegrationRef is the integration this WebAPI belongs to, e.g. \"github\" or \"team-a/github\". Required: every WebAPI is owned by an integration, which must already exist and cannot be deleted while this WebAPI exists. The reference says where the integration lives, independent of where the WebAPI lives — a bare \"name\" is a tenant-scoped (shared) integration, \"workspace/name\" is a workspace-scoped one — so a workspace WebAPI may reference a shared tenant integration by bare name. It is blank only in a catalogue definition's template, where Wayfinder fills it in when you install the integration."},
		"operations": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Operations are the templated HTTP operations exposed by this WebAPI. Each has a unique name and is invoked to produce a WebAPIInvocation.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"body": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Body is the request body template. Supports Go templating."},
			"headers": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Headers are additional headers for this operation. Values support Go templating.", ElementType: types.StringType},
			"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs defines the input schema for this operation — what inputs it expects.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"default_value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
				"description":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description iof the value"},
				"enum":           rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
				"identity_types": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
				"max_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
				"max_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
				"maximum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
				"min_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
				"min_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
				"minimum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
				"name":           rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name of the variable"},
				"optional":       rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
				"pattern":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
				"ref_type": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]rschema.Attribute{"filter": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
					"kind": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
				}},
				"repo_access":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
				"repo_branch_prefix": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
				"required_keys":      rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
				"schema_json":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
				"secret":             rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
				"type":               rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
			}}},
			"method": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Method is the HTTP method (GET, POST, PUT, PATCH, DELETE).", Validators: []validator.String{stringvalidator.OneOf("GET", "POST", "PUT", "PATCH", "DELETE")}},
			"name":   rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name is the unique identifier for this operation within the WebAPI."},
			"path":   rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Path is the URL path appended to the connection's base URL, e.g. \"/repos/${{ .Inputs.owner }}/${{ .Inputs.repo }}/issues\". Input values are substituted per invocation."},
			"response": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Response defines how to handle the response from this operation.", Attributes: map[string]rschema.Attribute{"store": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Store defines the response data to extract (via JQ) and store as ResourceData on the target resource.", Attributes: map[string]rschema.Attribute{"data_type": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DataType references the DataType resource whose schema validates the extracted Values. Its name — without any workspace prefix — is the key the data is stored under on the target resource. A bare name is the tenant's shared type, e.g. \"incident\"; \"workspace/name\" is one that workspace defined for itself, e.g. \"team-a/incident\". There is no fallback between the two, so a bare name always means the shared type. Only this web API's own workspace may be named: a tenant-scoped web API can use the shared types alone, and none can reach into another workspace. When set, Values must also be set (typed mode). When unset, the mode depends on Values: empty Values stores the response body verbatim (raw mode); non-empty Values extracts just those named fields with no schema (extraction-only mode)."},
				"items_to_parse": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ItemsToParse, when set, is a JQ expression yielding an array within the response, e.g. `.body.projects` for an endpoint that returns one entry per service. The store is then applied once per element, with the element exposed as `.item`, so a single call can write to many resources. Leave it empty when the response describes a single thing.\n\nA polled endpoint nearly always returns a collection, so this is how a scheduled call spreads its results across the resources they belong to."},
				"resource": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Resource selects which Wayfinder resource(s) the extracted data is stored against, by matching values pulled out of the response.\n\nLeave it unset for a call made in the context of something — a workflow step or a stack hook — where the data belongs to whatever triggered it. Set it for a call with no such context, above all a scheduled one: the data belongs to the resource it is *about*, not to the WebAPI that fetched it, and nothing else can work that out.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment is a JQ expression over the payload yielding the environment to match, e.g. `.body.labels.environment`. Omit to match any environment."},
					"kind":           rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Kind is the Wayfinder kind(s) to match — accepts a single kind name (`kind: StackInstance`) or a list of kinds (`kind: [StackInstance, KubeResource]`) to broadcast across kinds. Required once a data mapping is configured (enforced by validation); an endpoint-only webhook has no mapping.", ElementType: types.StringType},
					"labels":         rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Labels is a map of label key → JQ expression, e.g. {\"team\": \".body.commonLabels.team\"}. Each entry adds a label the target resource must carry with the resulting value.", ElementType: types.StringType},
					"name":           rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name is a JQ expression over the payload yielding the resource name to match exactly, e.g. `.body.labels.app`. Omit to match any name."},
					"on_multi_match": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "OnMultiMatch controls behaviour when the query returns >1 match. \"all\" (default) writes to every match; \"first\" picks the alphabetically first.\n\n- `all`: Writes the mapped data to every matched resource.\n\n- `first`: Writes only to the alphabetically first match.", Validators: []validator.String{stringvalidator.OneOf("all", "first")}},
					"workspace":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace is a JQ expression over the payload yielding the workspace to match, e.g. `.body.labels.workspace`. Omit to match any workspace."},
				}},
				"values": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Values is a map of output-field name → JQ expression, e.g. {\"issueNumber\": \".body.number\"}, evaluated against the response context (`.statusCode`, `.body`, `.headers`) to build the object of extracted fields. Required when DataType is set (typed, validated). Optional when DataType is empty: set it to expose named fields without a schema, or leave it empty to store the whole body (raw mode).", ElementType: types.StringType},
			}},
				"success_condition": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "SuccessCondition is a JQ boolean expression over the response that must evaluate to true for the call to be a success (e.g. `.statusCode == 200`). When empty the default is a 2xx status. A result that is not a boolean is a configuration error (reason=condition-error), not a silent failure."},
			}},
			"summary": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Summary is a short description of what this operation does."},
		}}},
		"schedules": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Schedules call operations automatically on a repeating interval, for sources that have no webhook and must be polled — cloud cost, seat and usage metrics, or a periodic posture snapshot.\n\nDeliberately separate from the operations themselves: WHAT an operation does is one thing, and WHEN to run it is another. The same operation can be scheduled more than once at different intervals with different inputs (this month's costs hourly, last month's daily), and an operation with no schedule is not a lesser kind of operation — it simply runs when a workflow, a stack hook or a person asks.\n\nEach entry maintains a Schedule resource, kept in step by writing this spec. Those Schedules are read-only: change them here.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"every_json": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Every is how long to wait between calls, e.g. \"15m\", \"1h\" or \"24h\". Pick a value comfortably longer than the call itself takes, and be mindful of what is at the other end: a slow daily report does not want a five-minute interval.", CustomType: jsontypes.NormalizedType{}},
			"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs are the values to call the operation with, validated against what it declares it accepts. A scheduled call has nobody to ask, so anything the operation needs has to be settled here: a query parameter, a lookback window, a page size. An operation that requires inputs cannot be scheduled without them.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"name": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
				"value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
			}}},
			"name":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name identifies this schedule within the WebAPI, and is what the Schedule resource is named after. Defaults to the operation name, which is all you need when an operation is scheduled once; name it explicitly to schedule the same operation more than once — this month's costs hourly and last month's daily, say.\n\nIt is the schedule's identity, so it is also what its run history hangs off: changing the interval of a named schedule adjusts that schedule, whereas renaming it starts a new one."},
			"operation": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Operation names which of this WebAPI's operations to call. It must be one the spec declares."},
			"suspend":   rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Suspend stops this schedule running without removing it, so it can be switched back on without losing the record of when it last ran."},
		}}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
func DataSourceSchema_web_api(ctx context.Context) dschema.Schema {
	return dschema.Schema{MarkdownDescription: "WebAPI is an outbound HTTP API you can call from Wayfinder: a reusable connection to a third-party system (base URL, credential and default headers) plus a set of templated operations Wayfinder invokes against it. It is the outbound counterpart of the inbound Webhook. Each operation call produces a WebAPIInvocation recording the request sent and the response received.", Attributes: map[string]dschema.Attribute{"spec_connection": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Connection defines how to reach the third-party system.", Attributes: map[string]dschema.Attribute{"auth": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Auth is the credential presented on each request. Leave it unset for a service that needs none.", Attributes: map[string]dschema.Attribute{"access": dschema.StringAttribute{Computed: true, MarkdownDescription: "Access is the most an MCP's calls may do in the repository CodeRepoRef names: \"read\" (the default) or \"write\". A call is made at the highest level up to this that the conversation asked for and its agent holds. A web API takes the level from each operation's method instead — \"read\" for GET and HEAD, \"write\" otherwise — and refuses this field.\n\n- `read`: Clones and fetches the repository and reads its CI results — which workflow run failed, which check is red, and what has been deployed.\n\n- `write`: Additionally pushes branches, opens pull requests and comments on them.", Validators: []validator.String{stringvalidator.OneOf("read", "write")}},
		"code_repo_ref":         dschema.StringAttribute{Computed: true, MarkdownDescription: "CodeRepoRef names the repository each call works on. Requests are authenticated with a short-lived token that Wayfinder mints for that repository alone, through the App it holds for the repository's provider. No secret is stored. Mutually exclusive with ExternalIdentityRef.\n\nIt is always a whole-field \"${{ .Inputs.<name> }}\" expression naming an input of kind CodeRepo, e.g. \"${{ .Inputs.codeRepo }}\", never a literal, so the repository is chosen by whatever uses the connection: an AI conversation answers it with the repository in its source context, and a web API invocation with one of its inputs. A call is refused unless the user, agent or workflow it is made for holds the access it needs in the repository's usableBy. Only GitHub repositories are supported."},
		"external_identity_ref": dschema.StringAttribute{Computed: true, MarkdownDescription: "ExternalIdentityRef names the ExternalIdentity whose credential authenticates the outbound calls. It is a single self-describing reference (\"name\", \"workspace/name\" or \"workspace/environment/name\") to an endpoint-family identity: BasicAuth, TLSClientCert, BearerToken, APIKey or OAuth2ClientCredentials. The identity's service host must match the connection's base URL host, so a credential minted for one service is never presented to another. Mutually exclusive with CodeRepoRef.\n\nAn MCP may also name an AWS identity (AWSIAMRole or AWSIAMUserKey). An AWS identity is accepted only where the connection's base URL is AWS's own MCP server, https://aws-mcp.<region>.api.aws.\n\nIt may be a literal, or a whole-field \"${{ .Inputs.<name> }}\" expression naming an input the object declares. It may be nothing else: it names a Wayfinder object, so it has to resolve without running the call — that is what lets the identity be permission-checked when you save, and what keeps it visible to \"what breaks if I delete this credential?\"."},
		"github_org_ref":        dschema.StringAttribute{Computed: true, MarkdownDescription: "GitHubOrgRef named the GitHub organisation a connection signed in to.\n\nDeprecated: replaced by codeRepoRef. A connection that still sets it cannot be saved, and its calls are refused."},
	}},
		"base_url": dschema.StringAttribute{Computed: true, MarkdownDescription: "BaseURL is the address requests are sent to, e.g. \"https://api.example.com\". It carries the scheme and host; what follows is the caller's — a WebAPI appends each operation's path, an MCP appends its own spec.path.\n\nIt may be a literal, or an expression over the inputs the object declares, e.g. \"https://api.${{ .Inputs.site }}\". An expression lets one shipped definition serve every tenant, each supplying its own value.\n\nRequired before the object may be enabled; one you have not finished configuring may leave it blank until then."},
		"headers":  dschema.MapAttribute{Computed: true, MarkdownDescription: "Headers are sent on every request, in addition to anything an individual operation adds. Values may be literals or expressions over the declared inputs. Do not set a credential header here — Auth applies the credential by its type, and a header set by hand bypasses that.\n\nOn an MCP a value may also read the arguments of the tool call it is sent with, as \"${{ .Args.<name> }}\", so one registration serves every repository or project an agent asks about instead of one per value. GitHub's hosted Actions server wants \"Mcp-Param-owner\" and \"Mcp-Param-repo\" that way: with \"${{ .Args.owner }}\" the agent passes owner and repo in the tool call, as the tool's own schema asks, and the call works. A header reading an argument the call did not carry is left off, so the server answers saying which value it wanted rather than acting on a blank one. A WebAPI has no such arguments and refuses the expression.", ElementType: types.StringType},
	}},
		"definition_ref": dschema.StringAttribute{Computed: true, MarkdownDescription: "DefinitionRef records the catalogue entry this WebAPI came from, as \"<definition>@<generation>\", e.g. \"wayfinder.github@3\". Set by Wayfinder when you install an integration from the catalogue; empty for WebAPIs you create directly. Read-only."},
		"description":    dschema.StringAttribute{Computed: true, MarkdownDescription: "Description is a short human-readable summary of what this WebAPI is for."},
		"enabled":        dschema.BoolAttribute{Computed: true, MarkdownDescription: "Enabled toggles whether operations on this WebAPI can be invoked. A disabled WebAPI is retained and visible but its operations are not executed."},
		"input_values": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "InputValues are the values this WebAPI was given for the inputs it declares. A WebAPI set up from a catalogue entry may leave a required value blank until you configure it, and stays disabled until you do.", Attributes: map[string]dschema.Attribute{"values": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Values are named input values matching the plan's ValueDefinitions. May contain template expressions (e.g. \"${{ .Vars.name }}\", \"${{ .Secrets.key }}\"). Resolved when Wayfinder applies the configuration — secret values are never stored here.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"name": dschema.StringAttribute{Computed: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
			"value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
		}}},
		}},
		"inputs": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Inputs declares the values this WebAPI needs before it can be used, so one definition can serve every tenant instead of hard-coding one tenant's address and credential. A connection field may reference them, e.g. \"https://api.${{ .Inputs.site }}\", as may any operation's path, body or headers.\n\nThese are the WebAPI's own configuration, settled once. They are not the arguments to a call: an operation declares those in its own inputs, and both share one .Inputs namespace, so a name declared here may not be redeclared by an operation.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"default_value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
			"description":    dschema.StringAttribute{Computed: true, MarkdownDescription: "Description iof the value"},
			"enum":           dschema.ListAttribute{Computed: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
			"identity_types": dschema.ListAttribute{Computed: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
			"max_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
			"max_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
			"maximum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
			"min_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
			"min_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
			"minimum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
			"name":           dschema.StringAttribute{Computed: true, MarkdownDescription: "Name of the variable"},
			"optional":       dschema.BoolAttribute{Computed: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
			"pattern":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
			"ref_type": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]dschema.Attribute{"filter": dschema.MapAttribute{Computed: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
				"kind": dschema.StringAttribute{Computed: true, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
			}},
			"repo_access":        dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
			"repo_branch_prefix": dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
			"required_keys":      dschema.ListAttribute{Computed: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
			"schema_json":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
			"secret":             dschema.BoolAttribute{Computed: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
			"type":               dschema.StringAttribute{Computed: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
		}}},
		"integration_ref": dschema.StringAttribute{Computed: true, MarkdownDescription: "IntegrationRef is the integration this WebAPI belongs to, e.g. \"github\" or \"team-a/github\". Required: every WebAPI is owned by an integration, which must already exist and cannot be deleted while this WebAPI exists. The reference says where the integration lives, independent of where the WebAPI lives — a bare \"name\" is a tenant-scoped (shared) integration, \"workspace/name\" is a workspace-scoped one — so a workspace WebAPI may reference a shared tenant integration by bare name. It is blank only in a catalogue definition's template, where Wayfinder fills it in when you install the integration."},
		"operations": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Operations are the templated HTTP operations exposed by this WebAPI. Each has a unique name and is invoked to produce a WebAPIInvocation.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"body": dschema.StringAttribute{Computed: true, MarkdownDescription: "Body is the request body template. Supports Go templating."},
			"headers": dschema.MapAttribute{Computed: true, MarkdownDescription: "Headers are additional headers for this operation. Values support Go templating.", ElementType: types.StringType},
			"inputs": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Inputs defines the input schema for this operation — what inputs it expects.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"default_value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
				"description":    dschema.StringAttribute{Computed: true, MarkdownDescription: "Description iof the value"},
				"enum":           dschema.ListAttribute{Computed: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
				"identity_types": dschema.ListAttribute{Computed: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
				"max_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
				"max_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
				"maximum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
				"min_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
				"min_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
				"minimum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
				"name":           dschema.StringAttribute{Computed: true, MarkdownDescription: "Name of the variable"},
				"optional":       dschema.BoolAttribute{Computed: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
				"pattern":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
				"ref_type": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]dschema.Attribute{"filter": dschema.MapAttribute{Computed: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
					"kind": dschema.StringAttribute{Computed: true, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
				}},
				"repo_access":        dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
				"repo_branch_prefix": dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
				"required_keys":      dschema.ListAttribute{Computed: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
				"schema_json":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
				"secret":             dschema.BoolAttribute{Computed: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
				"type":               dschema.StringAttribute{Computed: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
			}}},
			"method": dschema.StringAttribute{Computed: true, MarkdownDescription: "Method is the HTTP method (GET, POST, PUT, PATCH, DELETE).", Validators: []validator.String{stringvalidator.OneOf("GET", "POST", "PUT", "PATCH", "DELETE")}},
			"name":   dschema.StringAttribute{Computed: true, MarkdownDescription: "Name is the unique identifier for this operation within the WebAPI."},
			"path":   dschema.StringAttribute{Computed: true, MarkdownDescription: "Path is the URL path appended to the connection's base URL, e.g. \"/repos/${{ .Inputs.owner }}/${{ .Inputs.repo }}/issues\". Input values are substituted per invocation."},
			"response": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Response defines how to handle the response from this operation.", Attributes: map[string]dschema.Attribute{"store": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Store defines the response data to extract (via JQ) and store as ResourceData on the target resource.", Attributes: map[string]dschema.Attribute{"data_type": dschema.StringAttribute{Computed: true, MarkdownDescription: "DataType references the DataType resource whose schema validates the extracted Values. Its name — without any workspace prefix — is the key the data is stored under on the target resource. A bare name is the tenant's shared type, e.g. \"incident\"; \"workspace/name\" is one that workspace defined for itself, e.g. \"team-a/incident\". There is no fallback between the two, so a bare name always means the shared type. Only this web API's own workspace may be named: a tenant-scoped web API can use the shared types alone, and none can reach into another workspace. When set, Values must also be set (typed mode). When unset, the mode depends on Values: empty Values stores the response body verbatim (raw mode); non-empty Values extracts just those named fields with no schema (extraction-only mode)."},
				"items_to_parse": dschema.StringAttribute{Computed: true, MarkdownDescription: "ItemsToParse, when set, is a JQ expression yielding an array within the response, e.g. `.body.projects` for an endpoint that returns one entry per service. The store is then applied once per element, with the element exposed as `.item`, so a single call can write to many resources. Leave it empty when the response describes a single thing.\n\nA polled endpoint nearly always returns a collection, so this is how a scheduled call spreads its results across the resources they belong to."},
				"resource": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Resource selects which Wayfinder resource(s) the extracted data is stored against, by matching values pulled out of the response.\n\nLeave it unset for a call made in the context of something — a workflow step or a stack hook — where the data belongs to whatever triggered it. Set it for a call with no such context, above all a scheduled one: the data belongs to the resource it is *about*, not to the WebAPI that fetched it, and nothing else can work that out.", Attributes: map[string]dschema.Attribute{"environment": dschema.StringAttribute{Computed: true, MarkdownDescription: "Environment is a JQ expression over the payload yielding the environment to match, e.g. `.body.labels.environment`. Omit to match any environment."},
					"kind":           dschema.ListAttribute{Computed: true, MarkdownDescription: "Kind is the Wayfinder kind(s) to match — accepts a single kind name (`kind: StackInstance`) or a list of kinds (`kind: [StackInstance, KubeResource]`) to broadcast across kinds. Required once a data mapping is configured (enforced by validation); an endpoint-only webhook has no mapping.", ElementType: types.StringType},
					"labels":         dschema.MapAttribute{Computed: true, MarkdownDescription: "Labels is a map of label key → JQ expression, e.g. {\"team\": \".body.commonLabels.team\"}. Each entry adds a label the target resource must carry with the resulting value.", ElementType: types.StringType},
					"name":           dschema.StringAttribute{Computed: true, MarkdownDescription: "Name is a JQ expression over the payload yielding the resource name to match exactly, e.g. `.body.labels.app`. Omit to match any name."},
					"on_multi_match": dschema.StringAttribute{Computed: true, MarkdownDescription: "OnMultiMatch controls behaviour when the query returns >1 match. \"all\" (default) writes to every match; \"first\" picks the alphabetically first.\n\n- `all`: Writes the mapped data to every matched resource.\n\n- `first`: Writes only to the alphabetically first match.", Validators: []validator.String{stringvalidator.OneOf("all", "first")}},
					"workspace":      dschema.StringAttribute{Computed: true, MarkdownDescription: "Workspace is a JQ expression over the payload yielding the workspace to match, e.g. `.body.labels.workspace`. Omit to match any workspace."},
				}},
				"values": dschema.MapAttribute{Computed: true, MarkdownDescription: "Values is a map of output-field name → JQ expression, e.g. {\"issueNumber\": \".body.number\"}, evaluated against the response context (`.statusCode`, `.body`, `.headers`) to build the object of extracted fields. Required when DataType is set (typed, validated). Optional when DataType is empty: set it to expose named fields without a schema, or leave it empty to store the whole body (raw mode).", ElementType: types.StringType},
			}},
				"success_condition": dschema.StringAttribute{Computed: true, MarkdownDescription: "SuccessCondition is a JQ boolean expression over the response that must evaluate to true for the call to be a success (e.g. `.statusCode == 200`). When empty the default is a 2xx status. A result that is not a boolean is a configuration error (reason=condition-error), not a silent failure."},
			}},
			"summary": dschema.StringAttribute{Computed: true, MarkdownDescription: "Summary is a short description of what this operation does."},
		}}},
		"schedules": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Schedules call operations automatically on a repeating interval, for sources that have no webhook and must be polled — cloud cost, seat and usage metrics, or a periodic posture snapshot.\n\nDeliberately separate from the operations themselves: WHAT an operation does is one thing, and WHEN to run it is another. The same operation can be scheduled more than once at different intervals with different inputs (this month's costs hourly, last month's daily), and an operation with no schedule is not a lesser kind of operation — it simply runs when a workflow, a stack hook or a person asks.\n\nEach entry maintains a Schedule resource, kept in step by writing this spec. Those Schedules are read-only: change them here.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"every_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "Every is how long to wait between calls, e.g. \"15m\", \"1h\" or \"24h\". Pick a value comfortably longer than the call itself takes, and be mindful of what is at the other end: a slow daily report does not want a five-minute interval.", CustomType: jsontypes.NormalizedType{}},
			"inputs": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Inputs are the values to call the operation with, validated against what it declares it accepts. A scheduled call has nobody to ask, so anything the operation needs has to be settled here: a query parameter, a lookback window, a page size. An operation that requires inputs cannot be scheduled without them.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"name": dschema.StringAttribute{Computed: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
				"value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
			}}},
			"name":      dschema.StringAttribute{Computed: true, MarkdownDescription: "Name identifies this schedule within the WebAPI, and is what the Schedule resource is named after. Defaults to the operation name, which is all you need when an operation is scheduled once; name it explicitly to schedule the same operation more than once — this month's costs hourly and last month's daily, say.\n\nIt is the schedule's identity, so it is also what its run history hangs off: changing the interval of a named schedule adjusts that schedule, whereas renaming it starts a new one."},
			"operation": dschema.StringAttribute{Computed: true, MarkdownDescription: "Operation names which of this WebAPI's operations to call. It must be one the spec declares."},
			"suspend":   dschema.BoolAttribute{Computed: true, MarkdownDescription: "Suspend stops this schedule running without removing it, so it can be switched back on without losing the record of when it last ran."},
		}}},
		"id":          dschema.StringAttribute{Computed: true},
		"name":        dschema.StringAttribute{Required: true, Optional: false},
		"workspace":   dschema.StringAttribute{Required: false, Optional: true},
		"labels":      dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"annotations": dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"status":      dschema.SingleNestedAttribute{Computed: true, Attributes: map[string]dschema.Attribute{"status": dschema.StringAttribute{Computed: true}, "message": dschema.StringAttribute{Computed: true}, "detail": dschema.StringAttribute{Computed: true}}},
		"status_json": dschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
	}}
}
func ResourceSchema_webhook(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Webhook accepts signed HTTP POST deliveries from an external system at a secret ingest URL, and writes data extracted from each delivery onto the Wayfinder resources it matches. The signature, target-resource query and the values to store are all configured on the spec; every delivery is recorded as a WebhookInvocation.", Attributes: map[string]rschema.Attribute{"definition_ref": rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "DefinitionRef records the catalogue entry this webhook came from, as \"<definition>@<generation>\", e.g. \"wayfinder.github@3\". Set by Wayfinder when you install an integration from the catalogue; empty for webhooks you create directly. Read-only.", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"description":       rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a short description of what this webhook is for."},
		"enabled":           rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Enabled toggles whether this webhook accepts inbound deliveries. A disabled webhook rejects deliveries (recording the rejection) but keeps its ingest URL and configuration. Omitted means enabled — an explicit false is required to turn a webhook off. Webhooks created from a catalogue entry start disabled; turn them on once configured."},
		"integration_ref":   rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "IntegrationRef is the integration this webhook belongs to, e.g. \"github\" or \"team-a/github\". Required: every webhook is owned by an integration, which must already exist and cannot be deleted while this webhook exists. The reference says where the integration lives, independent of where the webhook lives — a bare \"name\" is a tenant-scoped (shared) integration, \"workspace/name\" is a workspace-scoped one — so a workspace webhook may reference a shared tenant integration by bare name. It is blank only in a catalogue definition's template, where Wayfinder fills it in when you install the integration."},
		"max_payload_bytes": rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxPayloadBytes caps the size of an inbound body, e.g. 1048576 for 1 MiB. Deliveries larger than this are rejected with HTTP 413."},
		"security": rschema.SingleNestedAttribute{Required: true, Optional: false, MarkdownDescription: "Security defines how inbound deliveries are authenticated and what HMAC algorithm/secret/header signals are expected.", Attributes: map[string]rschema.Attribute{"algorithm": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Algorithm is the HMAC algorithm the upstream uses to sign the body. \"none\" means URL secrecy only — accepted but not recommended for any payload an attacker could mint.\n\n- `hmac-sha256`: Verifies deliveries with an HMAC-SHA256 signature of the request body (e.g. GitHub's X-Hub-Signature-256).\n\n- `hmac-sha1`: Verifies deliveries with an HMAC-SHA1 signature of the request body.\n\n- `none`: Performs no signature verification, relying on the secrecy of the ingest URL alone. Not recommended for any payload an attacker could mint.", Validators: []validator.String{stringvalidator.OneOf("hmac-sha256", "hmac-sha1", "none")}},
			"request_id_header": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RequestIDHeader is the upstream's per-delivery unique ID header (e.g. X-GitHub-Delivery). Enables short-window dedup."},
			"secret_wo":         rschema.StringAttribute{Required: false, Optional: true, Sensitive: true, WriteOnly: true, MarkdownDescription: "Secret is the shared HMAC signing secret used to verify inbound delivery signatures. Required unless Algorithm is \"none\". Stored encrypted at rest and never returned by the API — supply it to set or rotate it, leave it blank on update to keep the stored value.\n\nWrite-only: never stored in state. Requires Terraform or OpenTofu 1.11 or later."},
			"secret_wo_version": rschema.StringAttribute{Optional: true, MarkdownDescription: "Change this value to send a new secret_wo to Wayfinder."},
			"signature_header":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "SignatureHeader is the HTTP header the upstream uses to carry the signature (e.g. \"X-Hub-Signature-256\"). Required unless Algorithm is \"none\"."},
			"signature_prefix":  rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "SignaturePrefix is stripped from the header value before comparison (e.g. \"sha256=\" for GitHub)."},
		}},
		"storage": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Storage defines what each delivery writes and where. Every delivery is applied to every entry, and each entry selects its own target resources, splits its own batched items and writes its own data entry. Optional: a webhook with no storage still records every delivery without writing to any resource, which lets you confirm connectivity and inspect real payloads before deciding what to store.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"data": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Data defines the DataType and JQ-mapped values written against the matched resource(s).", Attributes: map[string]rschema.Attribute{"data_type": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DataType references the DataType resource whose schema validates the mapped Values. Its name — without any workspace prefix — is the key the data is stored under on the target resource. A bare name is the tenant's shared type, e.g. \"incident\"; \"workspace/name\" is one that workspace defined for itself, e.g. \"team-a/incident\". There is no fallback between the two, so a bare name always means the shared type. Only this webhook's own workspace may be named: a tenant-scoped webhook can use the shared types alone, and no webhook can reach into another workspace. When set, Values must also be set (typed mode). When unset, the webhook runs in raw mode: the inbound body is stored verbatim under dataKey=<webhook name> with no schema check and no JQ extraction."},
			"keep_history": rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "KeepHistory controls write semantics. false (default) means each delivery overwrites the entry in place. true increments the generation and retains prior values as an audit trail."},
			"values":       rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Values is a map of stored-field name → JQ expression, e.g. {\"severity\": \".body.status\"}. Each expression is evaluated against the delivery to build the object that is stored. Required when DataType is set; must be empty when DataType is empty.", ElementType: types.StringType},
		}},
			"items_to_parse": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "ItemsToParse, when set, is a JQ expression yielding an array within the delivery, e.g. `.body.alerts` for a sender that batches several alerts into one POST. This configuration is then applied once per element, with the element exposed as `.item`. Leave it empty when each delivery carries a single record."},
			"resource": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Resource defines the query that selects the target resource(s) for this delivery.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment is a JQ expression over the payload yielding the environment to match, e.g. `.body.labels.environment`. Omit to match any environment."},
				"kind":           rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Kind is the Wayfinder kind(s) to match — accepts a single kind name (`kind: StackInstance`) or a list of kinds (`kind: [StackInstance, KubeResource]`) to broadcast across kinds. Required once a data mapping is configured (enforced by validation); an endpoint-only webhook has no mapping.", ElementType: types.StringType},
				"labels":         rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Labels is a map of label key → JQ expression, e.g. {\"team\": \".body.commonLabels.team\"}. Each entry adds a label the target resource must carry with the resulting value.", ElementType: types.StringType},
				"name":           rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name is a JQ expression over the payload yielding the resource name to match exactly, e.g. `.body.labels.app`. Omit to match any name."},
				"on_multi_match": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "OnMultiMatch controls behaviour when the query returns >1 match. \"all\" (default) writes to every match; \"first\" picks the alphabetically first.\n\n- `all`: Writes the mapped data to every matched resource.\n\n- `first`: Writes only to the alphabetically first match.", Validators: []validator.String{stringvalidator.OneOf("all", "first")}},
				"workspace":      rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace is a JQ expression over the payload yielding the workspace to match, e.g. `.body.labels.workspace`. Omit to match any workspace."},
			}},
		}}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
