func ResourceSchema_workflow(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Workflow is a reusable template that defines a named set of triggers and the tasks to run when one of them fires. It is the durable definition you author and keep; firing one of its triggers produces a WorkflowInvocation, a single run of the workflow's tasks, which Wayfinder then drives to completion.\n\nTasks run in parallel by default and each may declare the tasks it depends on, so a workflow can fan out and join. A task calls an HTTP integration operation, holds a conversation with an AI agent, reads a source repository, or runs a Wayfinder CLI command server-side.", Attributes: map[string]rschema.Attribute{"config": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Config is static, workflow-level configuration made available to task templates as `.Config.*`. It is fixed by the author and the same for every run of the workflow — a place for shared values such as a budget or an endpoint, distinct from per-run inputs.", ElementType: jsontypes.NormalizedType{}},
		"description": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a short, human-readable description of the workflow."},
		"enabled":     rschema.BoolAttribute{Optional: true, Computed: true, MarkdownDescription: "Enabled toggles whether this workflow's triggers fire. Omitted means enabled — an explicit false is required to turn a workflow off, so a workflow written before the toggle existed keeps running. Workflows installed from the catalogue start disabled; turn them on once configured.\n\nTurning one on is checked: everything the workflow names — the agents its tasks call, the web APIs they call, and the integrations behind those — must exist and be enabled. Its inputs are NOT checked here: they are supplied when it is invoked, and the run is where a missing value is refused.", PlanModifiers: []planmodifier.Bool{boolplanmodifier.UseStateForUnknown()}},
		"files": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Files declares the files this workflow's tasks read. A task names one by path, exactly as it would on a command line — `file: Wayfinder.yaml` runs `wf deploy --file Wayfinder.yaml` against these files and nothing else.\n\nA declared file is either carried by the workflow (its content is inlined here, written as \"!file <relative path>\" and loaded when the workflow is applied) or supplied by a checkout task at run time (no content). Declaring it either way means the spec says what the workflow reads, rather than the answer living in data attached to it.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"content": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Content is the file itself, carried by the workflow.\n\nAuthored as \"!file <relative path>\" — the Wayfinder include directive, the same one a KubeResourcePlan's manifests use — and replaced with the file's contents when the workflow is applied. The stored workflow therefore holds what its tasks will read, so reviewing the workflow is reviewing the object.\n\nEmpty means a checkout task supplies this file. That is the ordinary case for a workflow whose files live in a repository; content is for the case where they do not, or where one file is deliberately pinned to the workflow."},
			"kind": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Kind is what the file must contain, e.g. \"StackDefinition\" or \"CloudResourcePlan\". Optional, and checked when the workflow is written: a file that does not parse as its declared kind is an authoring error rather than a failed run at 3am. Leave it empty for content that has no kind — a Helm values file, or a webhook payload."},
			"path": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Path is what a task's parameter names, relative to the root of the files the run assembles — e.g. \"Wayfinder.yaml\", or \"plans/db.yaml\". Must be a clean relative path: no leading \"/\" and no \"..\" components."},
		}}},
		"suggested_roles": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "SuggestedRoles names the roles a tenant should grant this workflow so it can run. A workflow acts as itself, so one whose tasks run Wayfinder commands can do nothing until it holds a role that allows them. The author declares what it needs here (e.g. [\"tenant.manager\"]); the catalogue and the workflow's readiness surface them. Each must be a role a tenant user can grant.", ElementType: types.StringType},
		"tasks": rschema.MapNestedAttribute{Required: true, Optional: false, MarkdownDescription: "Tasks is the set of tasks to run, keyed by task name. Tasks run in parallel by default; a task that declares dependsOn waits for those tasks first. Any trigger starts a run of all the tasks — use a task's when condition to run it only in certain cases (for example only for a particular trigger).", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"action": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Action is the \"<integration>/<type>/<...>\" slash-path identifying the work to perform: the first segment names the owning integration, the second selects the kind of thing to run, and the rest names it. \"<integration>/webapi/<webapi>/<operation>\" runs an HTTP integration action; \"ai/agent/<name>\" runs a conversation with the named AIAgent, and its structured result becomes the task's output — name a tenant agent as \"ai/agent/<name>\" and one a workspace owns as \"ai/agent/<workspace>/<name>\" or \"ai/agent/<workspace>/<environment>/<name>\", where the workspace must be the workflow's own; \"ai/agent/wayfinder/<name>\" runs one of the agents Wayfinder ships, which any workflow may name; \"wf/<command>/<subcommand>...\" runs a Wayfinder CLI command server-side; \"checkout/github.com/<owner>/<repo>\" reads the named source repository into the run's files."},
			"ai": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "AI carries the settings that apply only to an \"ai/agent\" task: where the conversation is created, the source repository the agent works against, and the model and effort to run it on. Ignored by every other task type.", Attributes: map[string]rschema.Attribute{"effort": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Effort is how hard the model should think before answering in this task's conversation, overriding what its agent asks for: one of none, low, medium, high, xhigh or max. A level the model cannot reach is clamped to the nearest it can. It may be a `${{ }}` template, like the fields above."},
				"model": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Model runs this task's conversation on a model other than the one its agent declares, named as \"<provider>:<model>\" — \"anthropic:sonnet-5\", say, for the one task in a workflow that needs the harder thinking. It may be a `${{ }}` template, e.g. \"${{ .Config.model }}\", so the choice can live in the workflow's own configuration."},
				"placement": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Placement names where this task's conversation is created. Defaults to where the run is.", Attributes: map[string]rschema.Attribute{"environment": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Environment is the environment within that workspace the conversation is created in, e.g. \"dev\". Naming one without a workspace is refused: an environment belongs to a workspace, and the conversation needs both."},
					"workspace": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace is the workspace the conversation is created in, e.g. \"kteam\"."},
				}},
				"source_context": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "SourceContext binds the conversation to a source repository, so the agent's file tools read and write that repository. Required when the agent declares requiresSourceContext. Whether the agent may propose a change is declared on the source context itself, not here.", Attributes: map[string]rschema.Attribute{"branch": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Branch is the branch to read from. Empty resolves the CodeRepo's default branch, the same way it does for an interactive conversation."},
					"kind": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Kind identifies the source kind. Only \"github\" is meaningful for a workflow: a hands-off run has no client to serve a local filesystem.", Validators: []validator.String{stringvalidator.OneOf("github")}},
					"propose": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Propose, when set, lets the task's agent change the repository: its file tools may write as well as read, and it may commit those changes and open a pull request. Its presence IS the grant, so a task that omits it dispatches an agent that can only read.", Attributes: map[string]rschema.Attribute{"branch_prefix": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "BranchPrefix is prepended to the name of the branch the agent's changes are committed to. Must be a clean relative path, and conventionally ends with \"/\" so the branches group under it — e.g. \"wayfinder-ai/cost-control/\". Empty uses Wayfinder's own default prefix."},
						"follow_pull_request": rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "FollowPullRequest keeps the task's agent available after it opens a pull request: someone commenting on that pull request, or reviewing it, puts the agent back to work on it. The agent reads the pull request itself and decides what to do — nothing anyone wrote there is passed to it. Without this the run ends at the pull request, and a review left on it reaches nobody.\n\nThe agent must declare spec.supportsFollowPullRequests."},
					}},
					"repo":         rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Repo names the repository the agent reads from, as \"github.com/OWNER/REPO\", e.g. \"github.com/appvia/wayfinder\", or a ${{ }} template that renders to one."},
					"subdirectory": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Subdirectory constrains the agent's file tools, and any file it proposes, to a subtree of the repository. Must be a clean relative path — no \"..\" components and no absolute path. Empty means the repository root."},
				}},
			}},
			"checkout": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Checkout configures how much of a \"checkout/github.com/<owner>/<repo>\" task's repository to read — the ref and the subdirectory. Which repository is the action's own business. Rejected on any other action.", Attributes: map[string]rschema.Attribute{"ref": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Ref is the branch, tag or commit to read. Empty reads the repository's default branch. Whatever is given, the commit it resolves to is recorded on the run — the branch may move, but what ran does not."},
				"subdirectory": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Subdirectory reads only a subtree of the repository, and makes that subtree the root of the run's files: with \"stacks/payments\", a task reads \"Wayfinder.yaml\" for the file the repository holds at \"stacks/payments/Wayfinder.yaml\". Must be a clean relative path — no \"..\" components and no leading \"/\". Empty reads the whole repository."},
				"workspace":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Workspace is no longer used: the action names the repository, whichever workspace owns it. Saving a task that sets it is refused.\n\nDeprecated: name the repository in the action, as \"checkout/github.com/OWNER/REPO\"."},
			}},
			"continue_on_failure": rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "ContinueOnFailure marks this task as best-effort: if it fails, the tasks that depend on it still run, and the run as a whole still succeeds. Use it for a step whose failure is not worth abandoning the rest of the workflow for — inviting a user, posting a notification, tagging a resource.\n\nThe failure is not hidden: the task still reports as Failed with its reason, the run's message names every tolerated failure, and a dependent task can see what happened via `${{ .Tasks.<name>.failed }}`, `.phase`, and `.error.*` — so it can react (report it, take the other path) rather than only carry on."},
			"depends_on":          rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "DependsOn lists the names of tasks that must succeed before this task is scheduled. A task whose dependencies are all skipped is skipped; a task that joins several branches runs as soon as its un-skipped dependencies succeed. A dependency that failed normally takes this task down with it, unless that dependency declared continueOnFailure.", ElementType: types.StringType},
			"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs provides templated values for this task, resolved live at dispatch time against the run context (`.Inputs.*`, `.Tasks.<name>.output.*`).", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"name": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
				"value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
			}}},
			"when": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "When optionally gates whether this task runs: a `${{ }}` template expression evaluated against the run context just before the task would be dispatched. The task runs only when it renders to \"true\"; otherwise it is skipped (and tasks that depend solely on it are skipped in turn). Use it to run a task only in certain cases, for example only for a particular trigger (`${{ eq .Trigger.Name \"nightly\" }}`) or based on an upstream task's output."},
			"with": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "With provides a \"wf/...\" task's command parameters as named fields — each key is one of the command's own flags (or the reserved \"name\"/\"args\" positionals), typed exactly as the CLI defines it, and validated against the CLI's command schema when the workflow is written. Values are templated like Inputs. Rejected on other task types, whose parameters are their Inputs.", ElementType: jsontypes.NormalizedType{}},
		}}},
		"triggers": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Triggers declares the named conditions that start a run of this workflow. A trigger fires either manually (e.g. `wf invoke workflow`) or automatically when a matching Wayfinder resource event occurs. Each trigger starts its own independent run of the workflow. (Named `triggers` rather than `on` because a bare YAML `on:` key coerces to the boolean true.)", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"event": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Event is the resource event that fires this trigger, e.g. \"Created\". Set it together with Resource."},
			"manual": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Manual declares this trigger as manually fireable, with an optional input schema validated against the run subresource's supplied inputs.", Attributes: map[string]rschema.Attribute{"inputs": rschema.ListNestedAttribute{Required: false, Optional: true, MarkdownDescription: "Inputs is the schema of the inputs this trigger accepts (name, type and whether each is required). The values supplied when the trigger is fired are validated against it, and are available to task templates as `.Inputs.*`.", NestedObject: rschema.NestedAttributeObject{Attributes: map[string]rschema.Attribute{"default_value_json": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
				"description":    rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description iof the value"},
				"enum":           rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
				"identity_types": rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
				"max_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
				"max_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
				"maximum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
				"min_items":      rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
				"min_length":     rschema.Int64Attribute{Required: false, Optional: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
				"minimum":        rschema.Float64Attribute{Required: false, Optional: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
				"name":           rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name of the variable"},
				"optional":       rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
				"pattern":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
				"ref_type": rschema.SingleNestedAttribute{Required: false, Optional: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]rschema.Attribute{"filter": rschema.MapAttribute{Required: false, Optional: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
					"kind": rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
				}},
				"repo_access":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
				"repo_branch_prefix": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
				"required_keys":      rschema.ListAttribute{Required: false, Optional: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
				"schema_json":        rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
				"secret":             rschema.BoolAttribute{Required: false, Optional: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
				"type":               rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
			}}},
			}},
			"name":     rschema.StringAttribute{Required: true, Optional: false, MarkdownDescription: "Name uniquely identifies the trigger within the workflow, e.g. \"nightly\". Any trigger starts a run of every task; a task selects a particular trigger by referencing this name in its when condition (`${{ eq .Trigger.Name \"nightly\" }}`). The run's inputs are also available to task templates keyed under this name as `.On.<name>.*`."},
			"resource": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Resource is the kind of resource whose events fire this trigger, e.g. \"StackInstance\". Set it together with Event to fire the trigger automatically on a matching resource event."},
			"when":     rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "When is an optional condition gating the fire: a `${{ }}` template expression evaluated against the triggering resource. The trigger fires only when it renders to \"true\"; combine conditions with `and`/`or` in one expression, e.g. `${{ and (eq .Resource.spec.tier \"prod\") (ne .Resource.metadata.name \"test\") }}`."},
		}}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"workspace":      rschema.StringAttribute{Required: false, Optional: true, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
func DataSourceSchema_workflow(ctx context.Context) dschema.Schema {
	return dschema.Schema{MarkdownDescription: "Workflow is a reusable template that defines a named set of triggers and the tasks to run when one of them fires. It is the durable definition you author and keep; firing one of its triggers produces a WorkflowInvocation, a single run of the workflow's tasks, which Wayfinder then drives to completion.\n\nTasks run in parallel by default and each may declare the tasks it depends on, so a workflow can fan out and join. A task calls an HTTP integration operation, holds a conversation with an AI agent, reads a source repository, or runs a Wayfinder CLI command server-side.", Attributes: map[string]dschema.Attribute{"config": dschema.MapAttribute{Computed: true, MarkdownDescription: "Config is static, workflow-level configuration made available to task templates as `.Config.*`. It is fixed by the author and the same for every run of the workflow — a place for shared values such as a budget or an endpoint, distinct from per-run inputs.", ElementType: jsontypes.NormalizedType{}},
		"description": dschema.StringAttribute{Computed: true, MarkdownDescription: "Description is a short, human-readable description of the workflow."},
		"enabled":     dschema.BoolAttribute{Computed: true, MarkdownDescription: "Enabled toggles whether this workflow's triggers fire. Omitted means enabled — an explicit false is required to turn a workflow off, so a workflow written before the toggle existed keeps running. Workflows installed from the catalogue start disabled; turn them on once configured.\n\nTurning one on is checked: everything the workflow names — the agents its tasks call, the web APIs they call, and the integrations behind those — must exist and be enabled. Its inputs are NOT checked here: they are supplied when it is invoked, and the run is where a missing value is refused."},
		"files": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Files declares the files this workflow's tasks read. A task names one by path, exactly as it would on a command line — `file: Wayfinder.yaml` runs `wf deploy --file Wayfinder.yaml` against these files and nothing else.\n\nA declared file is either carried by the workflow (its content is inlined here, written as \"!file <relative path>\" and loaded when the workflow is applied) or supplied by a checkout task at run time (no content). Declaring it either way means the spec says what the workflow reads, rather than the answer living in data attached to it.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"content": dschema.StringAttribute{Computed: true, MarkdownDescription: "Content is the file itself, carried by the workflow.\n\nAuthored as \"!file <relative path>\" — the Wayfinder include directive, the same one a KubeResourcePlan's manifests use — and replaced with the file's contents when the workflow is applied. The stored workflow therefore holds what its tasks will read, so reviewing the workflow is reviewing the object.\n\nEmpty means a checkout task supplies this file. That is the ordinary case for a workflow whose files live in a repository; content is for the case where they do not, or where one file is deliberately pinned to the workflow."},
			"kind": dschema.StringAttribute{Computed: true, MarkdownDescription: "Kind is what the file must contain, e.g. \"StackDefinition\" or \"CloudResourcePlan\". Optional, and checked when the workflow is written: a file that does not parse as its declared kind is an authoring error rather than a failed run at 3am. Leave it empty for content that has no kind — a Helm values file, or a webhook payload."},
			"path": dschema.StringAttribute{Computed: true, MarkdownDescription: "Path is what a task's parameter names, relative to the root of the files the run assembles — e.g. \"Wayfinder.yaml\", or \"plans/db.yaml\". Must be a clean relative path: no leading \"/\" and no \"..\" components."},
		}}},
		"suggested_roles": dschema.ListAttribute{Computed: true, MarkdownDescription: "SuggestedRoles names the roles a tenant should grant this workflow so it can run. A workflow acts as itself, so one whose tasks run Wayfinder commands can do nothing until it holds a role that allows them. The author declares what it needs here (e.g. [\"tenant.manager\"]); the catalogue and the workflow's readiness surface them. Each must be a role a tenant user can grant.", ElementType: types.StringType},
		"tasks": dschema.MapNestedAttribute{Computed: true, MarkdownDescription: "Tasks is the set of tasks to run, keyed by task name. Tasks run in parallel by default; a task that declares dependsOn waits for those tasks first. Any trigger starts a run of all the tasks — use a task's when condition to run it only in certain cases (for example only for a particular trigger).", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"action": dschema.StringAttribute{Computed: true, MarkdownDescription: "Action is the \"<integration>/<type>/<...>\" slash-path identifying the work to perform: the first segment names the owning integration, the second selects the kind of thing to run, and the rest names it. \"<integration>/webapi/<webapi>/<operation>\" runs an HTTP integration action; \"ai/agent/<name>\" runs a conversation with the named AIAgent, and its structured result becomes the task's output — name a tenant agent as \"ai/agent/<name>\" and one a workspace owns as \"ai/agent/<workspace>/<name>\" or \"ai/agent/<workspace>/<environment>/<name>\", where the workspace must be the workflow's own; \"ai/agent/wayfinder/<name>\" runs one of the agents Wayfinder ships, which any workflow may name; \"wf/<command>/<subcommand>...\" runs a Wayfinder CLI command server-side; \"checkout/github.com/<owner>/<repo>\" reads the named source repository into the run's files."},
			"ai": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "AI carries the settings that apply only to an \"ai/agent\" task: where the conversation is created, the source repository the agent works against, and the model and effort to run it on. Ignored by every other task type.", Attributes: map[string]dschema.Attribute{"effort": dschema.StringAttribute{Computed: true, MarkdownDescription: "Effort is how hard the model should think before answering in this task's conversation, overriding what its agent asks for: one of none, low, medium, high, xhigh or max. A level the model cannot reach is clamped to the nearest it can. It may be a `${{ }}` template, like the fields above."},
				"model": dschema.StringAttribute{Computed: true, MarkdownDescription: "Model runs this task's conversation on a model other than the one its agent declares, named as \"<provider>:<model>\" — \"anthropic:sonnet-5\", say, for the one task in a workflow that needs the harder thinking. It may be a `${{ }}` template, e.g. \"${{ .Config.model }}\", so the choice can live in the workflow's own configuration."},
				"placement": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Placement names where this task's conversation is created. Defaults to where the run is.", Attributes: map[string]dschema.Attribute{"environment": dschema.StringAttribute{Computed: true, MarkdownDescription: "Environment is the environment within that workspace the conversation is created in, e.g. \"dev\". Naming one without a workspace is refused: an environment belongs to a workspace, and the conversation needs both."},
					"workspace": dschema.StringAttribute{Computed: true, MarkdownDescription: "Workspace is the workspace the conversation is created in, e.g. \"kteam\"."},
				}},
				"source_context": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "SourceContext binds the conversation to a source repository, so the agent's file tools read and write that repository. Required when the agent declares requiresSourceContext. Whether the agent may propose a change is declared on the source context itself, not here.", Attributes: map[string]dschema.Attribute{"branch": dschema.StringAttribute{Computed: true, MarkdownDescription: "Branch is the branch to read from. Empty resolves the CodeRepo's default branch, the same way it does for an interactive conversation."},
					"kind": dschema.StringAttribute{Computed: true, MarkdownDescription: "Kind identifies the source kind. Only \"github\" is meaningful for a workflow: a hands-off run has no client to serve a local filesystem.", Validators: []validator.String{stringvalidator.OneOf("github")}},
					"propose": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Propose, when set, lets the task's agent change the repository: its file tools may write as well as read, and it may commit those changes and open a pull request. Its presence IS the grant, so a task that omits it dispatches an agent that can only read.", Attributes: map[string]dschema.Attribute{"branch_prefix": dschema.StringAttribute{Computed: true, MarkdownDescription: "BranchPrefix is prepended to the name of the branch the agent's changes are committed to. Must be a clean relative path, and conventionally ends with \"/\" so the branches group under it — e.g. \"wayfinder-ai/cost-control/\". Empty uses Wayfinder's own default prefix."},
						"follow_pull_request": dschema.BoolAttribute{Computed: true, MarkdownDescription: "FollowPullRequest keeps the task's agent available after it opens a pull request: someone commenting on that pull request, or reviewing it, puts the agent back to work on it. The agent reads the pull request itself and decides what to do — nothing anyone wrote there is passed to it. Without this the run ends at the pull request, and a review left on it reaches nobody.\n\nThe agent must declare spec.supportsFollowPullRequests."},
					}},
					"repo":         dschema.StringAttribute{Computed: true, MarkdownDescription: "Repo names the repository the agent reads from, as \"github.com/OWNER/REPO\", e.g. \"github.com/appvia/wayfinder\", or a ${{ }} template that renders to one."},
					"subdirectory": dschema.StringAttribute{Computed: true, MarkdownDescription: "Subdirectory constrains the agent's file tools, and any file it proposes, to a subtree of the repository. Must be a clean relative path — no \"..\" components and no absolute path. Empty means the repository root."},
				}},
			}},
			"checkout": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Checkout configures how much of a \"checkout/github.com/<owner>/<repo>\" task's repository to read — the ref and the subdirectory. Which repository is the action's own business. Rejected on any other action.", Attributes: map[string]dschema.Attribute{"ref": dschema.StringAttribute{Computed: true, MarkdownDescription: "Ref is the branch, tag or commit to read. Empty reads the repository's default branch. Whatever is given, the commit it resolves to is recorded on the run — the branch may move, but what ran does not."},
				"subdirectory": dschema.StringAttribute{Computed: true, MarkdownDescription: "Subdirectory reads only a subtree of the repository, and makes that subtree the root of the run's files: with \"stacks/payments\", a task reads \"Wayfinder.yaml\" for the file the repository holds at \"stacks/payments/Wayfinder.yaml\". Must be a clean relative path — no \"..\" components and no leading \"/\". Empty reads the whole repository."},
				"workspace":    dschema.StringAttribute{Computed: true, MarkdownDescription: "Workspace is no longer used: the action names the repository, whichever workspace owns it. Saving a task that sets it is refused.\n\nDeprecated: name the repository in the action, as \"checkout/github.com/OWNER/REPO\"."},
			}},
			"continue_on_failure": dschema.BoolAttribute{Computed: true, MarkdownDescription: "ContinueOnFailure marks this task as best-effort: if it fails, the tasks that depend on it still run, and the run as a whole still succeeds. Use it for a step whose failure is not worth abandoning the rest of the workflow for — inviting a user, posting a notification, tagging a resource.\n\nThe failure is not hidden: the task still reports as Failed with its reason, the run's message names every tolerated failure, and a dependent task can see what happened via `${{ .Tasks.<name>.failed }}`, `.phase`, and `.error.*` — so it can react (report it, take the other path) rather than only carry on."},
			"depends_on":          dschema.ListAttribute{Computed: true, MarkdownDescription: "DependsOn lists the names of tasks that must succeed before this task is scheduled. A task whose dependencies are all skipped is skipped; a task that joins several branches runs as soon as its un-skipped dependencies succeed. A dependency that failed normally takes this task down with it, unless that dependency declared continueOnFailure.", ElementType: types.StringType},
			"inputs": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Inputs provides templated values for this task, resolved live at dispatch time against the run context (`.Inputs.*`, `.Tasks.<name>.output.*`).", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"name": dschema.StringAttribute{Computed: true, MarkdownDescription: "Name matches a ValueDefinition on the associated plan."},
				"value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "Value is a literal value or template expression, resolved at reconciliation time. Stored as json.RawMessage so non-string types (numbers, bools) survive YAML round-trips without forced quoting. Template expressions like \"${{ .Vars.x }}\" are stored as JSON strings.", CustomType: jsontypes.NormalizedType{}},
			}}},
			"when": dschema.StringAttribute{Computed: true, MarkdownDescription: "When optionally gates whether this task runs: a `${{ }}` template expression evaluated against the run context just before the task would be dispatched. The task runs only when it renders to \"true\"; otherwise it is skipped (and tasks that depend solely on it are skipped in turn). Use it to run a task only in certain cases, for example only for a particular trigger (`${{ eq .Trigger.Name \"nightly\" }}`) or based on an upstream task's output."},
			"with": dschema.MapAttribute{Computed: true, MarkdownDescription: "With provides a \"wf/...\" task's command parameters as named fields — each key is one of the command's own flags (or the reserved \"name\"/\"args\" positionals), typed exactly as the CLI defines it, and validated against the CLI's command schema when the workflow is written. Values are templated like Inputs. Rejected on other task types, whose parameters are their Inputs.", ElementType: jsontypes.NormalizedType{}},
		}}},
		"triggers": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Triggers declares the named conditions that start a run of this workflow. A trigger fires either manually (e.g. `wf invoke workflow`) or automatically when a matching Wayfinder resource event occurs. Each trigger starts its own independent run of the workflow. (Named `triggers` rather than `on` because a bare YAML `on:` key coerces to the boolean true.)", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"event": dschema.StringAttribute{Computed: true, MarkdownDescription: "Event is the resource event that fires this trigger, e.g. \"Created\". Set it together with Resource."},
			"manual": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "Manual declares this trigger as manually fireable, with an optional input schema validated against the run subresource's supplied inputs.", Attributes: map[string]dschema.Attribute{"inputs": dschema.ListNestedAttribute{Computed: true, MarkdownDescription: "Inputs is the schema of the inputs this trigger accepts (name, type and whether each is required). The values supplied when the trigger is fired are validated against it, and are available to task templates as `.Inputs.*`.", NestedObject: dschema.NestedAttributeObject{Attributes: map[string]dschema.Attribute{"default_value_json": dschema.StringAttribute{Computed: true, MarkdownDescription: "DefaultValue of this value", CustomType: jsontypes.NormalizedType{}},
				"description":    dschema.StringAttribute{Computed: true, MarkdownDescription: "Description iof the value"},
				"enum":           dschema.ListAttribute{Computed: true, MarkdownDescription: "Enum is the list of valid values for a string or number (or the values of lists/maps of those types). Ignored for other types.", ElementType: jsontypes.NormalizedType{}},
				"identity_types": dschema.ListAttribute{Computed: true, MarkdownDescription: "IdentityTypes lists the ExternalIdentity types this input accepts, e.g. [\"BearerToken\"] for an API that authenticates with a bearer token, or [\"BasicAuth\", \"BearerToken\"] where either will do. A value naming an identity of any other type is refused when it is supplied, rather than failing when the call runs. Leaving it empty accepts any identity type that can authenticate an outbound call. It may be set only on type=externalidentity, and is refused on every other type.", ElementType: types.StringType},
				"max_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxItems is the maximum number of items in the variable if a list or map"},
				"max_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MaxLength is the maximum number or length of the variable if a string"},
				"maximum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Maximum is the maximum numerical value of the variable if a number/float"},
				"min_items":      dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinItems is the minimum number of items in the variable if a list or map"},
				"min_length":     dschema.Int64Attribute{Computed: true, MarkdownDescription: "MinLength is the minimum number or length of the variable if a string"},
				"minimum":        dschema.Float64Attribute{Computed: true, MarkdownDescription: "Minimum is the minimum numerical value of the variable if a number/float"},
				"name":           dschema.StringAttribute{Computed: true, MarkdownDescription: "Name of the variable"},
				"optional":       dschema.BoolAttribute{Computed: true, MarkdownDescription: "Optional is true when no value need be supplied: the object declaring it can be saved, and switched on where it has a switch, without one. An unanswered optional value reads as its defaultValue when one is set, and as nothing otherwise. Whether whoever uses the object may supply it later is for that object to say."},
				"pattern":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Pattern is the pattern of the variable if a string. For list(string) and map(string), this is applied to each individual value in the list or map."},
				"ref_type": dschema.SingleNestedAttribute{Computed: true, MarkdownDescription: "RefType describes that this value is a reference to another Wayfinder resource. When set, the value is validated to be the name of an existing resource of the given kind, optionally filtered by field constraints.", Attributes: map[string]dschema.Attribute{"filter": dschema.MapAttribute{Computed: true, MarkdownDescription: "Filter is an optional set of dot-path field matchers on the referenced resource. Keys are dot-paths (e.g. \"spec.cloud\"), values are the expected string match. All entries must match (AND semantics).", ElementType: types.StringType},
					"kind": dschema.StringAttribute{Computed: true, MarkdownDescription: "Kind is the Wayfinder resource kind being referenced (e.g. \"ExternalIdentity\", \"CodeRepo\")"},
				}},
				"repo_access":        dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoAccess is how much of the repository the agent needs: \"read\" to clone and read it, \"propose\" to also commit to a fresh branch and open a pull request, or \"proposeWorkflows\" to also change the repository's CI workflow definitions. When empty, Wayfinder uses \"read\". Whoever supplies a repository must themselves be granted at least this much of it, and so must the agent, or the conversation is refused when it is created. It may be set only on type=coderepo, and is refused on every other type."},
				"repo_branch_prefix": dschema.StringAttribute{Computed: true, MarkdownDescription: "RepoBranchPrefix is prepended to the name of the branch the agent's changes are committed to, e.g. \"wayfinder-ai/cost-control/\". When empty, branches are prefixed \"wayfinder-ai/\". Set it so branch protection or CODEOWNERS rules in the repository match every branch this agent opens; whoever starts the conversation cannot change it. It may be set only on type=coderepo, and is refused on every other type."},
				"required_keys":      dschema.ListAttribute{Computed: true, MarkdownDescription: "RequiredKeys is the list of required keys for a map variable. Ignored for other types.", ElementType: types.StringType},
				"schema_json":        dschema.StringAttribute{Computed: true, MarkdownDescription: "Schema provides additional guidance as to the shape of the value when type=json.", CustomType: jsontypes.NormalizedType{}},
				"secret":             dschema.BoolAttribute{Computed: true, MarkdownDescription: "Secret indicates if the value is a secret and should be protected"},
				"type":               dschema.StringAttribute{Computed: true, MarkdownDescription: "Type is the type of the value\n\n- `string`: Is a string type\n\n- `number`: Is a number type (integer or floating point)\n\n- `bool`: Is a boolean type\n\n- `list(string)`: Is a list type of strings\n\n- `list(number)`: Is a list type of numbers\n\n- `list(bool)`: Is a list type of booleans\n\n- `map(string)`: Is a map type of strings\n\n- `map(number)`: Is a map type of numbers\n\n- `map(bool)`: Is a map type of booleans\n\n- `json`: Is an arbitrary JSON type, used to represent any complex input/output that isn't better represented by the other types. Note that no validation is possible for a plain JSON input.\n\n- `externalidentity`: Is a reference to an ExternalIdentity, naming the credential an outbound call authenticates with. The value is the identity's name and the scope it lives at (\"my-identity\", \"my-workspace/my-identity\" or \"my-workspace/my-env/my-identity\"), never credential material itself. Supplying a value resolves it: the identity must exist, you must be allowed to use it for what is calling, and its own kind must be one the definition's identityTypes accepts. A value naming an identity that fails any of those is refused when it is supplied, rather than failing when the call runs. It may only be declared where a definition is able to load an identity. It is refused on a CloudResourcePlan's inputs and outputs, a KubeResourcePlan's inputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs, all of which would otherwise receive the reference as a plain string.\n\n- `coderepo`: Is a reference to a CodeRepo, naming the repository an AI agent works on. The value names the repository as its provider does, \"github.com/OWNER/REPO\" (e.g. \"github.com/appvia/wayfinder\"), never a URL or a git credential. Use it on an AI agent's input where the repository is not fixed when the agent is written: the input sets how much of the repository the agent needs (repoAccess) and the branch prefix for its changes (repoBranchPrefix), and whoever starts the conversation supplies the repository. The conversation's spec.sourceContext is built from the value they supply. Supplying a value resolves it: the repository must exist, and the grant in its usableBy must cover the access the input asks for. That grant is checked against the person supplying the repository, not against whoever wrote the agent. The agent is checked separately, against the same repository, when the conversation is created. It may only be declared where a definition is able to load a repository and check that grant. It is refused on a CloudResourcePlan's and a KubeResourcePlan's inputs and outputs, a stack definition's vars, an IntegrationDefinition's paramDefs, and a repo template's inputs: each of those passes its values through as text to Terraform, a Helm chart, a rendered manifest or a scaffolded file, where the reference is only a plain string and no grant over the repository is checked.", Validators: []validator.String{stringvalidator.OneOf("string", "number", "bool", "list(string)", "list(number)", "list(bool)", "map(string)", "map(number)", "map(bool)", "json", "externalidentity", "coderepo")}},
			}}},
			}},
			"name":     dschema.StringAttribute{Computed: true, MarkdownDescription: "Name uniquely identifies the trigger within the workflow, e.g. \"nightly\". Any trigger starts a run of every task; a task selects a particular trigger by referencing this name in its when condition (`${{ eq .Trigger.Name \"nightly\" }}`). The run's inputs are also available to task templates keyed under this name as `.On.<name>.*`."},
			"resource": dschema.StringAttribute{Computed: true, MarkdownDescription: "Resource is the kind of resource whose events fire this trigger, e.g. \"StackInstance\". Set it together with Event to fire the trigger automatically on a matching resource event."},
			"when":     dschema.StringAttribute{Computed: true, MarkdownDescription: "When is an optional condition gating the fire: a `${{ }}` template expression evaluated against the triggering resource. The trigger fires only when it renders to \"true\"; combine conditions with `and`/`or` in one expression, e.g. `${{ and (eq .Resource.spec.tier \"prod\") (ne .Resource.metadata.name \"test\") }}`."},
		}}},
		"id":          dschema.StringAttribute{Computed: true},
		"name":        dschema.StringAttribute{Required: true, Optional: false},
		"workspace":   dschema.StringAttribute{Required: false, Optional: true},
		"labels":      dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"annotations": dschema.MapAttribute{Computed: true, ElementType: types.StringType},
		"status":      dschema.SingleNestedAttribute{Computed: true, Attributes: map[string]dschema.Attribute{"status": dschema.StringAttribute{Computed: true}, "message": dschema.StringAttribute{Computed: true}, "detail": dschema.StringAttribute{Computed: true}}},
		"status_json": dschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
	}}
}
func ResourceSchema_workspace(ctx context.Context) rschema.Schema {
	return rschema.Schema{MarkdownDescription: "Workspace is a team's or project's own area within a tenant, and the main unit of isolation below the tenant itself. It owns the resources created in it, holds the environments those resources are deployed into, and is the level most access is granted at - so one team's workspace stays separate from another's.", Attributes: map[string]rschema.Attribute{"description": rschema.StringAttribute{Required: false, Optional: true, MarkdownDescription: "Description is a human-readable description of what this workspace is for."},
		"slug":           rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "Slug is a short (max 8 character), immutable identifier for this workspace, unique within the tenant, e.g. \"plat\". It is generated from the workspace name on creation if not supplied. It is not needed for everyday use - reference the workspace by its name - but is available for length-constrained naming, such as cloud resource names in templates, where it is exposed as .WorkspaceSlug.", PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace(), stringplanmodifier.UseStateForUnknown()}},
		"type":           rschema.StringAttribute{Optional: true, Computed: true, MarkdownDescription: "Type is what this workspace is used for. Defaults to \"standard\" if not given.\n\n- `standard`: Is an ordinary workspace belonging to an application team, and is what a workspace is unless stated otherwise.\n\n- `infrastructure`\n\n- `admin`", PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}, Validators: []validator.String{stringvalidator.OneOf("standard", "infrastructure", "admin")}},
		"id":             rschema.StringAttribute{Computed: true, PlanModifiers: []planmodifier.String{stringplanmodifier.UseStateForUnknown()}},
		"name":           rschema.StringAttribute{Required: true, Optional: false, PlanModifiers: []planmodifier.String{stringplanmodifier.RequiresReplace()}},
		"labels":         rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"annotations":    rschema.MapAttribute{Optional: true, ElementType: types.StringType},
		"status":         rschema.SingleNestedAttribute{Computed: true, Attributes: map[string]rschema.Attribute{"status": rschema.StringAttribute{Computed: true}, "message": rschema.StringAttribute{Computed: true}, "detail": rschema.StringAttribute{Computed: true}}},
		"status_json":    rschema.StringAttribute{Computed: true, CustomType: jsontypes.NormalizedType{}},
		"timeouts":       timeouts.Attributes(ctx, timeouts.Opts{Create: true, Update: true, Delete: true}),
		"wait_for_ready": rschema.BoolAttribute{Optional: true, Computed: true, Default: booldefault.StaticBool(true)},
	}}
}
